window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[20]={"2001":{"example:2001:exzh":"Family is important.","example:2001:exzh2":"He works to support his family.","example:2001:exzh3":"Let's talk about family problems.","example:2001:exzh4":"It's important that a family is happy.","example:2001:exzh5":"I want to start a family."},"2004":{"example:2004:exzh":"He gave his best performance.","example:2004:exzh2":"I read a best-selling book.","example:2004:exzh3":"I think this dish is the best choice.","example:2004:exzh4":"I agree that her opinion is the best.","example:2004:exzh5":"This movie is one of the best."},"2005":{"example:2005:exzh":"He pressed me to answer quickly.","example:2005:exzh2":"Time is closing in.","example:2005:exzh3":"I was forced to make a decision.","example:2005:exzh4":"My mother pressed my little brother to apologize.","example:2005:exzh5":"A large typhoon is approaching Okinawa."},"2006":{"example:2006:exzh":"Marie is my friend.","example:2006:exzh2":"I watched a movie with Marie.","example:2006:exzh3":"Her name is Marie.","example:2006:exzh4":"Marie is a very kind person.","example:2006:exzh5":"Marie is good at cooking."},"2007":{"example:2007:exzh":"Investing comes with risks.","example:2007:exzh2":"There are risks in this plan.","example:2007:exzh3":"You can't avoid risk.","example:2007:exzh4":"He's good at taking risks.","example:2007:exzh5":"We need to consider the risks."},"2008":{"example:2008:exzh":"Metal is usually hard.","example:2008:exzh2":"This table is made of metal.","example:2008:exzh3":"Metal has many uses.","example:2008:exzh4":"He made metal crafts.","example:2008:exzh5":"Metal conducts heat."},"2009":{"example:2009:exzh":"We're using the latest technology.","example:2009:exzh2":"He watched the latest movie.","example:2009:exzh3":"This smartphone is the latest model.","example:2009:exzh4":"I checked the latest news.","example:2009:exzh5":"Let's talk about the latest trends."},"2011":{"example:2011:exzh":"Please take a look at this picture.","example:2011:exzh2":"When you've read the book, please take a look.","example:2011:exzh3":"Please look outside.","example:2011:exzh4":"Look, what an amazing view.","example:2011:exzh5":"Please take a look at this movie."},"2012":{"example:2012:exzh":"He is involved in the project.","example:2012:exzh2":"Being involved is important.","example:2012:exzh3":"Many people are involved in this issue.","example:2012:exzh4":"We discussed what involvement means.","example:2012:exzh5":"There is a responsibility to be involved."},"2013":{"example:2013:exzh":"Grandma is doing well.","example:2013:exzh2":"She went to see her grandma.","example:2013:exzh3":"Grandma is someone I like.","example:2013:exzh4":"Grandma cooked a meal.","example:2013:exzh5":"I brought a souvenir to my grandma.","grammar:2013:ex:trans":"Grandma is doing well.","grammar:2013:ex:structure":"ばあちゃんが元気です","grammar:2013:ex:explain":"This sentence uses 「が」 with a na-adjective predicate. 「ばあちゃん」 is an affectionate, casual way to say grandma, and 「が」 presents her as the one being described. 「元気」 is a na-adjective meaning \"healthy, full of energy\"; as a sentence-final predicate it drops the 「な」 and takes 「です」 directly, becoming 「元気です」. Using 「が」 rather than 「は」 gives the nuance of directly describing the state in front of you and presenting grandma as new information. 「〜が元気です」 is a very common pattern when asking after someone.","grammar:2013:ex:words:0:zh":"grandmother","grammar:2013:ex:words:0:note":"ばあちゃん","grammar:2013:ex:words:0:pos":"noun","grammar:2013:ex:words:1:zh":"(nominative)","grammar:2013:ex:words:1:pos":"particle","grammar:2013:ex:words:2:zh":"health","grammar:2013:ex:words:2:note":"げんき","grammar:2013:ex:words:2:pos":"na-adjective","grammar:2013:ex:words:3:zh":"(polite form)","grammar:2013:ex:words:3:pos":"copula","grammar:2013:ex:points:0":"❗「ばあ」: grandma (affectionate casual speech; usually 「ばあちゃん」 or 「おばあちゃん」; 「ばあ」 on its own is extremely casual).","grammar:2013:ex:points:1":"ばあちゃん: grandma.","grammar:2013:ex2:trans":"She went to see her grandma.","grammar:2013:ex2:structure":"ばあに会いに行った","grammar:2013:ex2:words:0:zh":"she","grammar:2013:ex2:words:0:note":"かのじょ","grammar:2013:ex2:words:0:pos":"pronoun","grammar:2013:ex2:words:1:zh":"(topic)","grammar:2013:ex2:words:1:pos":"particle","grammar:2013:ex2:words:2:zh":"grandmother","grammar:2013:ex2:words:2:note":"ばあ","grammar:2013:ex2:words:2:pos":"noun","grammar:2013:ex2:words:3:zh":"(object)","grammar:2013:ex2:words:3:pos":"particle","grammar:2013:ex2:words:4:zh":"meet","grammar:2013:ex2:words:4:note":"あい","grammar:2013:ex2:words:4:pos":"verb","grammar:2013:ex2:words:5:zh":"(purpose)","grammar:2013:ex2:words:5:pos":"particle","grammar:2013:ex2:words:6:zh":"went","grammar:2013:ex2:words:6:note":"いった","grammar:2013:ex2:words:6:pos":"verb","grammar:2013:ex2:points:0":"❗〜に会いに行く: to go to see … (masu-form of a verb + に = purpose).","grammar:2013:ex2:points:1":"会いに行く: to go to see.","grammar:2013:ex3:trans":"Grandma is someone I like.","grammar:2013:ex3:structure":"ばあは〜の好きな人です","grammar:2013:ex3:words:0:zh":"grandmother","grammar:2013:ex3:words:0:note":"ばあ","grammar:2013:ex3:words:0:pos":"noun","grammar:2013:ex3:words:1:zh":"(topic)","grammar:2013:ex3:words:1:pos":"particle","grammar:2013:ex3:words:2:zh":"I","grammar:2013:ex3:words:2:note":"わたし","grammar:2013:ex3:words:2:pos":"pronoun","grammar:2013:ex3:words:3:zh":"'s","grammar:2013:ex3:words:3:pos":"particle","grammar:2013:ex3:words:4:zh":"to like","grammar:2013:ex3:words:4:note":"すき","grammar:2013:ex3:words:4:pos":"na-adjective","grammar:2013:ex3:words:5:zh":"(attributive form)","grammar:2013:ex3:words:5:pos":"auxiliary verb","grammar:2013:ex3:words:6:zh":"person","grammar:2013:ex3:words:6:note":"ひと","grammar:2013:ex3:words:6:pos":"noun","grammar:2013:ex3:words:7:zh":"is","grammar:2013:ex3:words:7:pos":"copula","grammar:2013:ex3:points:0":"❗好きな人: someone you like (好き + な).","grammar:2013:ex3:points:1":"好きな人: someone you like.","grammar:2013:ex4:trans":"Grandma made a meal.","grammar:2013:ex4:structure":"ばあが料理を作った","grammar:2013:ex4:words:0:zh":"grandmother","grammar:2013:ex4:words:0:note":"ばあ","grammar:2013:ex4:words:0:pos":"noun","grammar:2013:ex4:words:1:zh":"(nominative)","grammar:2013:ex4:words:1:pos":"particle","grammar:2013:ex4:words:2:zh":"meal","grammar:2013:ex4:words:2:note":"りょうり","grammar:2013:ex4:words:2:pos":"noun","grammar:2013:ex4:words:3:zh":"(object marker)","grammar:2013:ex4:words:3:pos":"particle","grammar:2013:ex4:words:4:zh":"did","grammar:2013:ex4:words:4:note":"つくった","grammar:2013:ex4:words:4:pos":"verb","grammar:2013:ex4:points:0":"❗料理を作る: to cook, to make a meal.","grammar:2013:ex4:points:1":"料理を作る: to cook.","grammar:2013:ex5:trans":"I brought my grandma a souvenir.","grammar:2013:ex5:structure":"ばあにお土産を持って行きました","grammar:2013:ex5:words:0:zh":"I","grammar:2013:ex5:words:0:note":"わたし","grammar:2013:ex5:words:0:pos":"pronoun","grammar:2013:ex5:words:1:zh":"(topic)","grammar:2013:ex5:words:1:pos":"particle","grammar:2013:ex5:words:2:zh":"grandmother","grammar:2013:ex5:words:2:note":"ばあ","grammar:2013:ex5:words:2:pos":"noun","grammar:2013:ex5:words:3:zh":"(object)","grammar:2013:ex5:words:3:pos":"particle","grammar:2013:ex5:words:4:zh":"souvenir","grammar:2013:ex5:words:4:note":"おみやげ","grammar:2013:ex5:words:4:pos":"noun","grammar:2013:ex5:words:5:zh":"(object marker)","grammar:2013:ex5:words:5:pos":"particle","grammar:2013:ex5:words:6:zh":"carry","grammar:2013:ex5:words:6:note":"もって","grammar:2013:ex5:words:6:pos":"verb","grammar:2013:ex5:words:7:zh":"went","grammar:2013:ex5:words:7:note":"いきました","grammar:2013:ex5:words:7:pos":"verb","grammar:2013:ex5:points:0":"❗お土産: souvenir, local specialty; 持って行く = to take along.","grammar:2013:ex5:points:1":"お土産: souvenir."},"2014":{"example:2014:exzh":"What's inside this box?","example:2014:exzh2":"It's empty inside.","example:2014:exzh3":"I saw what was inside the present.","example:2014:exzh4":"What's inside is really important.","example:2014:exzh5":"Please check the contents."},"2015":{"example:2015:exzh":"He suddenly appeared.","example:2015:exzh2":"It came out in a new style.","example:2015:exzh3":"When the moon is out, I somehow feel at ease.","example:2015:exzh4":"My name appeared on TV.","example:2015:exzh5":"She came out and surprised everyone.","grammar:2015:ex:trans":"He suddenly appeared.","grammar:2015:ex:structure":"突然出てきました","grammar:2015:ex:explain":"The key here is 「出てくる」, a directional auxiliary verb. 「出る」 is an intransitive verb meaning 'to come out, to appear'; its te-form 「出て」 plus 「くる」 shows the action happening toward the speaker, coming closer from far away — 'to pop out, to show up' — and then it becomes the past tense 「出てきました」. The 「突然」 in front is the adverb 'suddenly', which strengthens the sense that the appearance was unexpected. 「彼は」 marks him as the topic with 「は」. Compared with just 「出た」, adding 「くる」 conveys more of the movement and immediacy of popping out toward me.","grammar:2015:ex:words:0:zh":"he","grammar:2015:ex:words:0:note":"かれ","grammar:2015:ex:words:0:pos":"pronoun","grammar:2015:ex:words:1:zh":"(topic)","grammar:2015:ex:words:1:pos":"particle","grammar:2015:ex:words:2:zh":"suddenly","grammar:2015:ex:words:2:note":"とつぜん","grammar:2015:ex:words:2:pos":"adverb","grammar:2015:ex:words:3:zh":"came out","grammar:2015:ex:words:3:note":"でてきました","grammar:2015:ex:words:3:pos":"verb","grammar:2015:ex:points:0":"❗出る (でる): to come out, to appear, (of the moon or sun) to rise (intransitive verb); 出てくる = to pop out, to show up.","grammar:2015:ex:points:1":"出る: to appear.","grammar:2015:ex2:trans":"It appeared in a new style.","grammar:2015:ex2:structure":"新しいスタイルで出てきた","grammar:2015:ex2:words:0:zh":"new","grammar:2015:ex2:words:0:note":"あたらしい","grammar:2015:ex2:words:0:pos":"adjective","grammar:2015:ex2:words:1:zh":"style","grammar:2015:ex2:words:1:note":"loanword","grammar:2015:ex2:words:1:pos":"noun","grammar:2015:ex2:words:2:zh":"(a state)","grammar:2015:ex2:words:2:pos":"particle","grammar:2015:ex2:words:3:zh":"came out","grammar:2015:ex2:words:3:note":"でてきた","grammar:2015:ex2:words:3:pos":"verb","grammar:2015:ex2:points:0":"❗スタイル: style, look (style); 〜で出てくる = to appear in …","grammar:2015:ex2:points:1":"出てくる: to show up.","grammar:2015:ex3:trans":"When the moon is out, somehow it feels reassuring.","grammar:2015:ex3:structure":"月が出ていると〜安心する","grammar:2015:ex3:words:0:zh":"the moon","grammar:2015:ex3:words:0:note":"つき","grammar:2015:ex3:words:0:pos":"noun","grammar:2015:ex3:words:1:zh":"(nominative)","grammar:2015:ex3:words:1:pos":"particle","grammar:2015:ex3:words:2:zh":"exposing","grammar:2015:ex3:words:2:note":"でている","grammar:2015:ex3:words:2:pos":"verb","grammar:2015:ex3:words:3:zh":"(condition)","grammar:2015:ex3:words:3:pos":"particle","grammar:2015:ex3:words:4:zh":"for some reason","grammar:2015:ex3:words:4:pos":"adverb","grammar:2015:ex3:words:5:zh":"feel at ease","grammar:2015:ex3:words:5:note":"あんしんする","grammar:2015:ex3:words:5:pos":"verb","grammar:2015:ex3:points:0":"❗月が出る: the moon rises (出る is an intransitive verb); なぜか = for some reason.","grammar:2015:ex3:points:1":"月が出る: the moon comes out.","grammar:2015:ex4:trans":"My name appeared on TV.","grammar:2015:ex4:structure":"〜に〜が出た","grammar:2015:ex4:explain":"「テレビに」 marks the medium or place where the name appeared. 「自分の名前」 means one's own name; in this sentence the translation takes it as the speaker's name. 「が」 marks the thing that appeared. 「出た」 is the plain past form of 「出る」, showing that the name has already appeared.","grammar:2015:ex4:words:0:zh":"TV","grammar:2015:ex4:words:0:pos":"noun","grammar:2015:ex4:words:1:zh":"(the place or medium where it appears)","grammar:2015:ex4:words:1:pos":"particle","grammar:2015:ex4:words:2:zh":"oneself","grammar:2015:ex4:words:2:note":"じぶん","grammar:2015:ex4:words:2:pos":"pronoun","grammar:2015:ex4:words:3:zh":"(possession)","grammar:2015:ex4:words:3:pos":"particle","grammar:2015:ex4:words:4:zh":"name","grammar:2015:ex4:words:4:note":"なまえ","grammar:2015:ex4:words:4:pos":"noun","grammar:2015:ex4:words:5:zh":"(nominative)","grammar:2015:ex4:words:5:pos":"particle","grammar:2015:ex4:words:6:zh":"appearance","grammar:2015:ex4:words:6:note":"で","grammar:2015:ex4:words:6:pos":"verb","grammar:2015:ex4:words:7:zh":"(past)","grammar:2015:ex4:words:7:pos":"auxiliary verb","grammar:2015:ex4:points:0":"「出る」 is an intransitive verb, so the thing that appears is marked with 「が」.","grammar:2015:ex4:points:1":"「テレビに出る」 can mean a person appearing on TV, or text or images showing up on TV.","grammar:2015:ex5:trans":"She appeared and startled everyone.","grammar:2015:ex5:structure":"出て、皆を驚かせた","grammar:2015:ex5:words:0:zh":"she","grammar:2015:ex5:words:0:note":"かのじょ","grammar:2015:ex5:words:0:pos":"pronoun","grammar:2015:ex5:words:1:zh":"(topic)","grammar:2015:ex5:words:1:pos":"particle","grammar:2015:ex5:words:2:zh":"appearance","grammar:2015:ex5:words:2:note":"でて","grammar:2015:ex5:words:2:pos":"verb","grammar:2015:ex5:words:3:zh":"everyone","grammar:2015:ex5:words:3:note":"みんな","grammar:2015:ex5:words:3:pos":"pronoun","grammar:2015:ex5:words:4:zh":"(object marker)","grammar:2015:ex5:words:4:pos":"particle","grammar:2015:ex5:words:5:zh":"was startled","grammar:2015:ex5:words:5:note":"おどろかせた","grammar:2015:ex5:words:5:pos":"verb","grammar:2015:ex5:points:0":"❗驚かせる: to surprise someone (the causative of 驚く); 皆を驚かせる = to startle everyone.","grammar:2015:ex5:points:1":"驚かせる: to surprise.","exam:2015:zh":"When you press this button, the next question appears on the screen, so please choose your answer.","exam:2015:why":"The question appears on the screen, so 「出る」 is used. 「消える」 means to disappear, the opposite of the situation where you then choose an answer."},"2016":{"example:2016:exzh":"Seeing that child's pitiful appearance made me sad.","example:2016:exzh2":"I sympathize with the pitiful situation.","example:2016:exzh3":"I can't forget his sorrowful expression.","example:2016:exzh4":"I want to help animals in distress.","example:2016:exzh5":"Her heartrending story touched my heart."},"2017":{"example:2017:exzh":"The jury's judgment is important.","example:2017:exzh2":"He was chosen as a juror.","example:2017:exzh3":"The jury's report was harsh.","example:2017:exzh4":"The jury ruled guilty.","example:2017:exzh5":"The jury must consider the matter carefully."},"2018":{"example:2018:exzh":"She works as a monk.","example:2018:exzh2":"The monk helped me.","example:2018:exzh3":"He went to meet the monk.","example:2018:exzh4":"Talking with the monk is enjoyable.","example:2018:exzh5":"My sister became a monk."},"2019":{"example:2019:exzh":"I felt embarrassed.","example:2019:exzh2":"I was so embarrassed that my face turned red.","example:2019:exzh3":"I'm too embarrassed to make eye contact.","example:2019:exzh4":"She felt embarrassed.","example:2019:exzh5":"When I feel embarrassed, I want to be alone.","grammar:2019:ex:trans":"I felt embarrassed.","grammar:2019:ex:structure":"恥ずかしい思いをしました","grammar:2019:ex:explain":"This sentence uses the set collocation 「〜思いをする」. 「恥ずかしい思いをする」 literally means 'to go through an embarrassing feeling', but in practice it equals 'to feel embarrassed, to feel ashamed' — a fixed expression. 「恥ずかしい」 is an i-adjective modifying the noun 「思い」 (a feeling), 「を」 marks that object, and 「しました」 is the polite past of 「する」. Note that 「思い」 here is not simply 'a thought' but an emotional experience you go through, so learn the whole phrase as an idiom rather than translating it word by word.","grammar:2019:ex:words:0:zh":"I","grammar:2019:ex:words:0:note":"わたし","grammar:2019:ex:words:0:pos":"pronoun","grammar:2019:ex:words:1:zh":"(topic)","grammar:2019:ex:words:1:pos":"particle","grammar:2019:ex:words:2:zh":"embarrassed","grammar:2019:ex:words:2:note":"はずかしい","grammar:2019:ex:words:2:pos":"adjective","grammar:2019:ex:words:3:zh":"feelings","grammar:2019:ex:words:3:note":"おもい","grammar:2019:ex:words:3:pos":"noun","grammar:2019:ex:words:4:zh":"(object marker)","grammar:2019:ex:words:4:pos":"particle","grammar:2019:ex:words:5:zh":"went through","grammar:2019:ex:words:5:pos":"verb","grammar:2019:ex:points:0":"❗恥ずかしい (はずかしい): embarrassed, ashamed (an adjective whose dictionary form ends in い); 恥ずかしい思いをする = to feel embarrassed.","grammar:2019:ex:points:1":"恥ずかしい: embarrassed.","grammar:2019:ex2:trans":"My face went red from embarrassment.","grammar:2019:ex2:structure":"i-adjective くて、〜が i-adjective くなった","grammar:2019:ex2:explain":"「恥ずかしくて」 comes from 「恥ずかしい」 and here gives the reason for the blushing. 「顔が赤くなった」 describes the face turning red from how it was before. 「赤い」 becomes 「赤く」 and then takes 「なる」; the point is that the state changed, not just that the face was red to begin with.","grammar:2019:ex2:words:0:zh":"embarrassed, shy","grammar:2019:ex2:words:0:note":"はずかしく","grammar:2019:ex2:words:0:pos":"i-adjective","grammar:2019:ex2:words:1:zh":"(links cause and result)","grammar:2019:ex2:words:1:pos":"particle","grammar:2019:ex2:words:2:zh":"face","grammar:2019:ex2:words:2:note":"かお","grammar:2019:ex2:words:2:pos":"noun","grammar:2019:ex2:words:3:zh":"(nominative)","grammar:2019:ex2:words:3:pos":"particle","grammar:2019:ex2:words:4:zh":"red","grammar:2019:ex2:words:4:note":"あかく","grammar:2019:ex2:words:4:pos":"i-adjective","grammar:2019:ex2:words:5:zh":"become","grammar:2019:ex2:words:5:pos":"verb","grammar:2019:ex2:words:6:zh":"(past)","grammar:2019:ex2:words:6:pos":"auxiliary verb","grammar:2019:ex2:points:0":"Changing an i-adjective's 「い」 to 「くて」 lets it link to the next clause and show cause.","grammar:2019:ex2:points:1":"「赤くなる」 uses 'i-adjective く + なる' to show becoming a certain state.","grammar:2019:ex2:points:2":"「なった」 is the plain past form of 「なる」, and sounds more casual.","grammar:2019:ex3:trans":"Because I'm embarrassed, I can't make eye contact.","grammar:2019:ex3:structure":"恥ずかしいので、目を合わせられません","grammar:2019:ex3:words:0:zh":"embarrassed","grammar:2019:ex3:words:0:note":"はずかしい","grammar:2019:ex3:words:0:pos":"adjective","grammar:2019:ex3:words:1:zh":"because","grammar:2019:ex3:words:1:pos":"particle","grammar:2019:ex3:words:2:zh":"eye(s)","grammar:2019:ex3:words:2:note":"め","grammar:2019:ex3:words:2:pos":"noun","grammar:2019:ex3:words:3:zh":"(object marker)","grammar:2019:ex3:words:3:pos":"particle","grammar:2019:ex3:words:4:zh":"can't meet (eyes)","grammar:2019:ex3:words:4:note":"あわせられません","grammar:2019:ex3:words:4:pos":"verb","grammar:2019:ex3:points:0":"❗目を合わせる: to make eye contact, to look each other in the eye; 〜られない = can't …","grammar:2019:ex3:points:1":"目を合わせる: to make eye contact.","grammar:2019:ex4:trans":"She felt embarrassed at the time.","grammar:2019:ex4:structure":"〜は＋i-adjectiveと感じていた","grammar:2019:ex4:explain":"「彼女は」 sets her as the topic, and 「恥ずかしいと」 states what she felt. 「感じていた」 shows that she was in that feeling at the time. By describing her inner feeling through 「感じる」, you can express a third person's state of mind.","grammar:2019:ex4:words:0:zh":"she","grammar:2019:ex4:words:0:note":"かのじょ","grammar:2019:ex4:words:0:pos":"pronoun","grammar:2019:ex4:words:1:zh":"(topic)","grammar:2019:ex4:words:1:pos":"particle","grammar:2019:ex4:words:2:zh":"embarrassed, shy","grammar:2019:ex4:words:2:note":"はずかしい","grammar:2019:ex4:words:2:pos":"i-adjective","grammar:2019:ex4:words:3:zh":"(quotes the content of the feeling)","grammar:2019:ex4:words:3:pos":"particle","grammar:2019:ex4:words:4:zh":"to feel, to sense","grammar:2019:ex4:words:4:note":"かんじ","grammar:2019:ex4:words:4:pos":"verb","grammar:2019:ex4:words:5:zh":"(links a state expression)","grammar:2019:ex4:words:5:pos":"particle","grammar:2019:ex4:words:6:zh":"(indicates a continuing state)","grammar:2019:ex4:words:6:pos":"verb","grammar:2019:ex4:words:7:zh":"(past)","grammar:2019:ex4:words:7:pos":"auxiliary verb","grammar:2019:ex4:points:0":"The 「と」 in 「と感じる」 marks the content of what is felt.","grammar:2019:ex4:points:1":"「〜ていた」 shows a state that continued at a point or over a period in the past.","grammar:2019:ex4:points:2":"When an i-adjective is followed by the quotative 「と」, it takes the plain form directly, with no 「だ」.","grammar:2019:ex5:trans":"When I'm embarrassed, I want to be alone.","grammar:2019:ex5:structure":"恥ずかしい時は、一人になりたい","grammar:2019:ex5:words:0:zh":"embarrassed","grammar:2019:ex5:words:0:note":"はずかしい","grammar:2019:ex5:words:0:pos":"adjective","grammar:2019:ex5:words:1:zh":"time","grammar:2019:ex5:words:1:note":"とき","grammar:2019:ex5:words:1:pos":"noun","grammar:2019:ex5:words:2:zh":"(topic)","grammar:2019:ex5:words:2:pos":"particle","grammar:2019:ex5:words:3:zh":"one person","grammar:2019:ex5:words:3:note":"ひとり","grammar:2019:ex5:words:3:pos":"noun","grammar:2019:ex5:words:4:zh":"(result)","grammar:2019:ex5:words:4:pos":"particle","grammar:2019:ex5:words:5:zh":"want to become","grammar:2019:ex5:words:5:note":"なりたい","grammar:2019:ex5:words:5:pos":"verb","grammar:2019:ex5:points:0":"❗一人になる: to be alone; 恥ずかしい時 = when you feel embarrassed.","grammar:2019:ex5:points:1":"一人になる: to be alone."},"2020":{"example:2020:exzh":"He is an injured athlete.","example:2020:exzh2":"Because of an injury, I can't take part in the match.","example:2020:exzh3":"If you get injured, call for help right away.","example:2020:exzh4":"I helped an injured animal.","example:2020:exzh5":"I'll report the details of the injury."},"2021":{"example:2021:exzh":"I think looks matter.","example:2021:exzh2":"She is kind, contrary to how she looks.","example:2021:exzh3":"I try not to care about appearances.","example:2021:exzh4":"That appearance isn't their true personality.","example:2021:exzh5":"I'm working hard to improve my appearance."},"2022":{"example:2022:exzh":"We are friends.","example:2022:exzh2":"Let's help each other as companions.","example:2022:exzh3":"I want to cherish the bonds between companions.","example:2022:exzh4":"People with the same hobbies got together.","example:2022:exzh5":"Let's support each other as companions."},"2023":{"example:2023:exzh":"She has been missing since two days ago.","example:2023:exzh2":"If someone goes missing, contact the police.","example:2023:exzh3":"The reasons people go missing are complicated.","example:2023:exzh4":"The investigation into the disappearance is ongoing.","example:2023:exzh5":"I'll provide information about the missing person."},"2024":{"example:2024:exzh":"On rainy days, we spend time under the roof.","example:2024:exzh2":"The new house has a big roof.","example:2024:exzh3":"In winter, snow sometimes falls off the roof.","example:2024:exzh4":"I repaired the roof of the house.","example:2024:exzh5":"Our house has a flat roof.","grammar:2024:ex:trans":"On rainy days, we spend our time under the eaves.","grammar:2024:ex:structure":"屋根の下で過ごします","grammar:2024:ex:explain":"The key here is 「で」 marking a place. The 「で」 in 「屋根の下で過ごします」 shows where the action takes place — 'spend time under the eaves'. 「屋根の下」 uses 「の」 to join 'roof' and 'under' into 'under the roof'. The opening 「雨の日は」 uses 「は」 to present 'rainy days' as both topic and condition. 「過ごします」 is the polite form of 「過ごす」 (to spend time, to live). Note that 「に」 marks where something exists, while 「で」 marks where an action happens; here it's an action, so 「で」 is used.","grammar:2024:ex:words:0:zh":"rain","grammar:2024:ex:words:0:note":"あめ","grammar:2024:ex:words:0:pos":"noun","grammar:2024:ex:words:1:zh":"'s","grammar:2024:ex:words:1:pos":"particle","grammar:2024:ex:words:2:zh":"day","grammar:2024:ex:words:2:note":"ひ","grammar:2024:ex:words:2:pos":"noun","grammar:2024:ex:words:3:zh":"(topic)","grammar:2024:ex:words:3:pos":"particle","grammar:2024:ex:words:4:zh":"rooftop","grammar:2024:ex:words:4:note":"やね","grammar:2024:ex:words:4:pos":"noun","grammar:2024:ex:words:5:zh":"'s","grammar:2024:ex:words:5:pos":"particle","grammar:2024:ex:words:6:zh":"under","grammar:2024:ex:words:6:note":"した","grammar:2024:ex:words:6:pos":"noun","grammar:2024:ex:words:7:zh":"(place)","grammar:2024:ex:words:7:pos":"particle","grammar:2024:ex:words:8:zh":"spend","grammar:2024:ex:words:8:note":"すごします","grammar:2024:ex:words:8:pos":"verb","grammar:2024:ex:points:0":"❗屋根 (やね): roof; 屋根の下 = under the eaves, under a roof.","grammar:2024:ex:points:1":"屋根: roof.","grammar:2024:ex2:trans":"The new house has a big roof.","grammar:2024:ex2:structure":"〜は大きな屋根があります","grammar:2024:ex2:words:0:zh":"new","grammar:2024:ex2:words:0:note":"あたらしい","grammar:2024:ex2:words:0:pos":"adjective","grammar:2024:ex2:words:1:zh":"house","grammar:2024:ex2:words:1:note":"いえ","grammar:2024:ex2:words:1:pos":"noun","grammar:2024:ex2:words:2:zh":"(topic)","grammar:2024:ex2:words:2:pos":"particle","grammar:2024:ex2:words:3:zh":"big","grammar:2024:ex2:words:3:note":"おおきな","grammar:2024:ex2:words:3:pos":"pre-noun adjectival","grammar:2024:ex2:words:4:zh":"rooftop","grammar:2024:ex2:words:4:note":"やね","grammar:2024:ex2:words:4:pos":"noun","grammar:2024:ex2:words:5:zh":"(nominative)","grammar:2024:ex2:words:5:pos":"particle","grammar:2024:ex2:words:6:zh":"there is / are","grammar:2024:ex2:words:6:pos":"verb","grammar:2024:ex2:points:0":"❗大きな屋根: a big roof.","grammar:2024:ex2:points:1":"大きな屋根: a big roof.","grammar:2024:ex3:trans":"In winter, snow sometimes falls off the roof.","grammar:2024:ex3:structure":"屋根から雪が落ちることがあります","grammar:2024:ex3:words:0:zh":"winter","grammar:2024:ex3:words:0:note":"ふゆ","grammar:2024:ex3:words:0:pos":"noun","grammar:2024:ex3:words:1:zh":"(point in time)","grammar:2024:ex3:words:1:pos":"particle","grammar:2024:ex3:words:2:zh":"(contrast)","grammar:2024:ex3:words:2:pos":"particle","grammar:2024:ex3:words:3:zh":"rooftop","grammar:2024:ex3:words:3:note":"やね","grammar:2024:ex3:words:3:pos":"noun","grammar:2024:ex3:words:4:zh":"from","grammar:2024:ex3:words:4:pos":"particle","grammar:2024:ex3:words:5:zh":"snow","grammar:2024:ex3:words:5:note":"ゆき","grammar:2024:ex3:words:5:pos":"noun","grammar:2024:ex3:words:6:zh":"(nominative)","grammar:2024:ex3:words:6:pos":"particle","grammar:2024:ex3:words:7:zh":"to fall","grammar:2024:ex3:words:7:note":"おちる","grammar:2024:ex3:words:7:pos":"verb","grammar:2024:ex3:words:8:zh":"(nominalizer)","grammar:2024:ex3:words:8:pos":"noun","grammar:2024:ex3:words:9:zh":"(nominative)","grammar:2024:ex3:words:9:pos":"particle","grammar:2024:ex3:words:10:zh":"there is / are","grammar:2024:ex3:words:10:pos":"verb","grammar:2024:ex3:points:0":"❗屋根から落ちる: to fall from the roof (から = starting point); 〜ことがある = sometimes happens.","grammar:2024:ex3:points:1":"屋根から落ちる: fall from the roof.","grammar:2024:ex4:trans":"I repaired the roof of the house.","grammar:2024:ex4:structure":"家の屋根を修理しました","grammar:2024:ex4:words:0:zh":"house","grammar:2024:ex4:words:0:note":"いえ","grammar:2024:ex4:words:0:pos":"noun","grammar:2024:ex4:words:1:zh":"'s","grammar:2024:ex4:words:1:pos":"particle","grammar:2024:ex4:words:2:zh":"rooftop","grammar:2024:ex4:words:2:note":"やね","grammar:2024:ex4:words:2:pos":"noun","grammar:2024:ex4:words:3:zh":"(object marker)","grammar:2024:ex4:words:3:pos":"particle","grammar:2024:ex4:words:4:zh":"repaired","grammar:2024:ex4:words:4:note":"しゅうりしました","grammar:2024:ex4:words:4:pos":"verb","grammar:2024:ex4:points:0":"❗屋根を修理する: repair the roof.","grammar:2024:ex4:points:1":"屋根を修理: repair the roof.","grammar:2024:ex5:trans":"My house has a flat roof.","grammar:2024:ex5:structure":"私の家はフラット屋根です","grammar:2024:ex5:words:0:zh":"I","grammar:2024:ex5:words:0:note":"わたし","grammar:2024:ex5:words:0:pos":"pronoun","grammar:2024:ex5:words:1:zh":"'s","grammar:2024:ex5:words:1:pos":"particle","grammar:2024:ex5:words:2:zh":"house","grammar:2024:ex5:words:2:note":"いえ","grammar:2024:ex5:words:2:pos":"noun","grammar:2024:ex5:words:3:zh":"(topic)","grammar:2024:ex5:words:3:pos":"particle","grammar:2024:ex5:words:4:zh":"flat roof","grammar:2024:ex5:words:4:note":"フラットやね","grammar:2024:ex5:words:4:pos":"noun","grammar:2024:ex5:words:5:zh":"is","grammar:2024:ex5:words:5:pos":"copula","grammar:2024:ex5:points:0":"❗フラット屋根: flat roof (flat + 屋根); also called 「陸屋根（ろくやね）」.","grammar:2024:ex5:points:1":"フラット屋根: flat roof."},"2025":{"example:2025:exzh":"I've been working from home more often.","example:2025:exzh2":"My home is in a quiet place.","example:2025:exzh3":"I join remote meetings from home.","example:2025:exzh4":"I relax at home on weekends.","example:2025:exzh5":"I invited friends to my home."},"2026":{"example:2026:exzh":"The fire alarm went off, so I went outside right away.","example:2026:exzh2":"After the alarm is lifted, we'll go back inside.","example:2026:exzh3":"If an alert is issued, pay attention.","example:2026:exzh4":"An earthquake alert was issued, so I evacuated right away.","example:2026:exzh5":"The alarm went off, so I turned on the TV."},"2027":{"example:2027:exzh":"I buy fresh vegetables at the market.","example:2027:exzh2":"The market is bustling on weekends.","example:2027:exzh3":"Many people visit the market.","example:2027:exzh4":"There is a shop in the market that sells fish.","example:2027:exzh5":"I like the atmosphere of the market."},"2028":{"example:2028:exzh":"I put on a hat and go out.","example:2028:exzh2":"He is wearing a scarf.","example:2028:exzh3":"On cold days, I wear gloves.","example:2028:exzh4":"She is always wearing lovely earrings.","example:2028:exzh5":"I put on my watch every morning.","grammar:2028:ex:trans":"I put on a hat and go out.","grammar:2028:ex:structure":"〜を着けて外に出ます","grammar:2028:ex:explain":"The core of this sentence is the te-form linking two actions. 「着けて」 is the te-form of 「着ける」 (put on), and it is followed by 「外に出ます」; the te-form strings put on a hat and go out together in order, meaning put on a hat and then go out. The te-form is the most common way to link actions in Japanese, and the actions come in sequence. The 「を」 in 「帽子を」 marks the object, and the 「に」 in 「外に」 marks the direction of movement. The subject is omitted and the actions flow together, which is the natural way to describe a series of behaviors.","grammar:2028:ex:words:0:zh":"hat","grammar:2028:ex:words:0:note":"ぼうし","grammar:2028:ex:words:0:pos":"noun","grammar:2028:ex:words:1:zh":"(object marker)","grammar:2028:ex:words:1:pos":"particle","grammar:2028:ex:words:2:zh":"put on","grammar:2028:ex:words:2:note":"つけて","grammar:2028:ex:words:2:pos":"verb","grammar:2028:ex:words:3:zh":"outside","grammar:2028:ex:words:3:note":"そと","grammar:2028:ex:words:3:pos":"noun","grammar:2028:ex:words:4:zh":"(destination)","grammar:2028:ex:words:4:pos":"particle","grammar:2028:ex:words:5:zh":"go out","grammar:2028:ex:words:5:note":"でます","grammar:2028:ex:words:5:pos":"verb","grammar:2028:ex:points:0":"❗着ける (つける): put on, wear (hats, accessories, etc.).","grammar:2028:ex:points:1":"〜て: te-form link (put on + go out).","grammar:2028:ex2:trans":"He's wearing a scarf.","grammar:2028:ex2:structure":"〜を着けています","grammar:2028:ex2:words:0:zh":"he","grammar:2028:ex2:words:0:note":"かれ","grammar:2028:ex2:words:0:pos":"pronoun","grammar:2028:ex2:words:1:zh":"(topic)","grammar:2028:ex2:words:1:pos":"particle","grammar:2028:ex2:words:2:zh":"scarf","grammar:2028:ex2:words:2:note":"loanword","grammar:2028:ex2:words:2:pos":"noun","grammar:2028:ex2:words:3:zh":"(object marker)","grammar:2028:ex2:words:3:pos":"particle","grammar:2028:ex2:words:4:zh":"is wearing","grammar:2028:ex2:words:4:note":"つけています","grammar:2028:ex2:words:4:pos":"verb","grammar:2028:ex2:points:0":"スカーフを着ける: wear a scarf.","grammar:2028:ex2:points:1":"〜ている: the state of wearing it.","grammar:2028:ex3:trans":"I wear gloves on cold days.","grammar:2028:ex3:structure":"〜には〜を着けます","grammar:2028:ex3:words:0:zh":"cold","grammar:2028:ex3:words:0:note":"さむい","grammar:2028:ex3:words:0:pos":"adjective","grammar:2028:ex3:words:1:zh":"day","grammar:2028:ex3:words:1:note":"ひ","grammar:2028:ex3:words:1:pos":"noun","grammar:2028:ex3:words:2:zh":"(point in time)","grammar:2028:ex3:words:2:pos":"particle","grammar:2028:ex3:words:3:zh":"(contrast)","grammar:2028:ex3:words:3:pos":"particle","grammar:2028:ex3:words:4:zh":"gloves","grammar:2028:ex3:words:4:note":"てぶくろ","grammar:2028:ex3:words:4:pos":"noun","grammar:2028:ex3:words:5:zh":"(object marker)","grammar:2028:ex3:words:5:pos":"particle","grammar:2028:ex3:words:6:zh":"put on","grammar:2028:ex3:words:6:note":"つけます","grammar:2028:ex3:words:6:pos":"verb","grammar:2028:ex3:points:0":"手袋を着ける: put on gloves (はめる is also common).","grammar:2028:ex3:points:1":"寒い日には: on cold days.","grammar:2028:ex4:trans":"She always wears pretty earrings.","grammar:2028:ex4:structure":"〜を着けています","grammar:2028:ex4:words:0:zh":"she","grammar:2028:ex4:words:0:note":"かのじょ","grammar:2028:ex4:words:0:pos":"pronoun","grammar:2028:ex4:words:1:zh":"(topic)","grammar:2028:ex4:words:1:pos":"particle","grammar:2028:ex4:words:2:zh":"always","grammar:2028:ex4:words:2:pos":"adverb","grammar:2028:ex4:words:3:zh":"beautiful","grammar:2028:ex4:words:3:note":"すてき","grammar:2028:ex4:words:3:pos":"na-adjective","grammar:2028:ex4:words:4:zh":"(attributive form)","grammar:2028:ex4:words:4:pos":"auxiliary verb","grammar:2028:ex4:words:5:zh":"earrings","grammar:2028:ex4:words:5:note":"loanword","grammar:2028:ex4:words:5:pos":"noun","grammar:2028:ex4:words:6:zh":"(object marker)","grammar:2028:ex4:words:6:pos":"particle","grammar:2028:ex4:words:7:zh":"is wearing","grammar:2028:ex4:words:7:note":"つけています","grammar:2028:ex4:words:7:pos":"verb","grammar:2028:ex4:points:0":"素敵なピアス: pretty earrings.","grammar:2028:ex4:points:1":"〜を着けている: be wearing…","grammar:2028:ex5:trans":"I put on a watch every morning.","grammar:2028:ex5:structure":"〜を着けます","grammar:2028:ex5:words:0:zh":"I","grammar:2028:ex5:words:0:note":"わたし","grammar:2028:ex5:words:0:pos":"pronoun","grammar:2028:ex5:words:1:zh":"(topic)","grammar:2028:ex5:words:1:pos":"particle","grammar:2028:ex5:words:2:zh":"every morning","grammar:2028:ex5:words:2:note":"まいあさ","grammar:2028:ex5:words:2:pos":"adverb","grammar:2028:ex5:words:3:zh":"watch","grammar:2028:ex5:words:3:note":"とけい","grammar:2028:ex5:words:3:pos":"noun","grammar:2028:ex5:words:4:zh":"(object marker)","grammar:2028:ex5:words:4:pos":"particle","grammar:2028:ex5:words:5:zh":"put on","grammar:2028:ex5:words:5:note":"つけます","grammar:2028:ex5:words:5:pos":"verb","grammar:2028:ex5:points:0":"時計を着ける: put on a watch.","grammar:2028:ex5:points:1":"毎朝: every morning."},"2029":{"example:2029:exzh":"He still hasn't come.","example:2029:exzh2":"I still have work that isn't finished.","example:2029:exzh3":"That news still hasn't been confirmed.","example:2029:exzh4":"The cold days are still continuing.","example:2029:exzh5":"My opinion still hasn't changed."},"2030":{"example:2030:exzh":"I like eating ice cream in summer.","example:2030:exzh2":"Ice cream is sweet and delicious.","example:2030:exzh3":"I went out for ice cream with a friend.","example:2030:exzh4":"I like chocolate-flavored ice cream the best.","example:2030:exzh5":"If you eat too much ice cream, your stomach will hurt.","grammar:2030:ex:trans":"I like eating ice cream in summer.","grammar:2030:ex:structure":"〜のが好きです","grammar:2030:ex:explain":"The core of this sentence is 「〜のが好き」, which expresses liking. 「食べるのが好き」 nominalizes the verb 「食べる」 with 「の」 into the act of eating, marks it with 「が」 as the thing that is liked, and joins it to 「好き」 (a na-adjective). This is the standard pattern for saying you like doing something: plain verb ＋ 「のが好きです」. At the front, 「夏は」 makes summer the topic and also the setting. Note that in Japanese the thing you like takes 「が」, not 「を」 — that is a feature of adjectives like 「好き」.","grammar:2030:ex:words:0:zh":"summer","grammar:2030:ex:words:0:note":"なつ","grammar:2030:ex:words:0:pos":"noun","grammar:2030:ex:words:1:zh":"(topic)","grammar:2030:ex:words:1:pos":"particle","grammar:2030:ex:words:2:zh":"ice cream","grammar:2030:ex:words:2:note":"loanword","grammar:2030:ex:words:2:pos":"noun","grammar:2030:ex:words:3:zh":"(object marker)","grammar:2030:ex:words:3:pos":"particle","grammar:2030:ex:words:4:zh":"eat","grammar:2030:ex:words:4:note":"たべる","grammar:2030:ex:words:4:pos":"verb","grammar:2030:ex:words:5:zh":"(nominalizer)","grammar:2030:ex:words:5:pos":"particle","grammar:2030:ex:words:6:zh":"(object)","grammar:2030:ex:words:6:pos":"particle","grammar:2030:ex:words:7:zh":"to like","grammar:2030:ex:words:7:note":"すき","grammar:2030:ex:words:7:pos":"na-adjective","grammar:2030:ex:words:8:zh":"(polite form)","grammar:2030:ex:words:8:pos":"copula","grammar:2030:ex:points:0":"アイスクリーム: ice cream.","grammar:2030:ex:points:1":"〜のが好き: to like doing…","grammar:2030:ex2:trans":"Ice cream is sweet and delicious.","grammar:2030:ex2:structure":"〜は〜くて〜です","grammar:2030:ex2:words:0:zh":"ice cream","grammar:2030:ex2:words:0:note":"loanword","grammar:2030:ex2:words:0:pos":"noun","grammar:2030:ex2:words:1:zh":"(topic)","grammar:2030:ex2:words:1:pos":"particle","grammar:2030:ex2:words:2:zh":"sweet","grammar:2030:ex2:words:2:note":"あまくて","grammar:2030:ex2:words:2:pos":"adjective","grammar:2030:ex2:words:3:zh":"delicious","grammar:2030:ex2:words:3:note":"おいしい","grammar:2030:ex2:words:3:pos":"adjective","grammar:2030:ex2:words:4:zh":"(polite form)","grammar:2030:ex2:words:4:pos":"copula","grammar:2030:ex2:points:0":"❗〜くて: (adjectives linking) … and …","grammar:2030:ex2:points:1":"甘くて美味しい: sweet and tasty.","grammar:2030:ex3:trans":"I went to eat ice cream with a friend.","grammar:2030:ex3:structure":"友達と＋アイスクリームを食べに＋行きました","grammar:2030:ex3:words:0:zh":"friend","grammar:2030:ex3:words:0:note":"ともだち; friend","grammar:2030:ex3:words:0:pos":"noun","grammar:2030:ex3:words:1:zh":"with","grammar:2030:ex3:words:1:pos":"particle","grammar:2030:ex3:words:2:zh":"ice cream","grammar:2030:ex3:words:2:pos":"noun","grammar:2030:ex3:words:3:zh":"object marker","grammar:2030:ex3:words:3:pos":"particle","grammar:2030:ex3:words:4:zh":"eat","grammar:2030:ex3:words:4:note":"たべ; the masu-form stem of 食べる","grammar:2030:ex3:words:4:pos":"verb","grammar:2030:ex3:words:5:zh":"purpose","grammar:2030:ex3:words:5:pos":"particle","grammar:2030:ex3:words:6:zh":"go","grammar:2030:ex3:words:6:note":"いき; masu-form stem of 行く","grammar:2030:ex3:words:6:pos":"verb","grammar:2030:ex3:words:7:zh":"polite past","grammar:2030:ex3:words:7:pos":"auxiliary verb","grammar:2030:ex3:points:0":"「アイスクリームを食べる」 uses the object directly, meaning eat ice cream.","grammar:2030:ex3:points:1":"「動詞ます形語幹＋に行く」 means going somewhere in order to do something.","grammar:2030:ex4:trans":"Chocolate ice cream is my favorite.","grammar:2030:ex4:structure":"チョコレート味のアイスクリーム＋が＋一番好きです","grammar:2030:ex4:words:0:zh":"chocolate","grammar:2030:ex4:words:0:pos":"noun","grammar:2030:ex4:words:1:zh":"flavor","grammar:2030:ex4:words:1:note":"あじ; flavor","grammar:2030:ex4:words:1:pos":"noun","grammar:2030:ex4:words:2:zh":"'s","grammar:2030:ex4:words:2:pos":"particle","grammar:2030:ex4:words:3:zh":"ice cream","grammar:2030:ex4:words:3:pos":"noun","grammar:2030:ex4:words:4:zh":"subject marker","grammar:2030:ex4:words:4:pos":"particle","grammar:2030:ex4:words:5:zh":"the most","grammar:2030:ex4:words:5:note":"いちばん; most","grammar:2030:ex4:words:5:pos":"adverb","grammar:2030:ex4:words:6:zh":"to like","grammar:2030:ex4:words:6:note":"すき; like","grammar:2030:ex4:words:6:pos":"na-adjective","grammar:2030:ex4:words:7:zh":"is","grammar:2030:ex4:words:7:pos":"copula","grammar:2030:ex4:points:0":"「チョコレート味の」 comes before 「アイスクリーム」 to describe the flavor.","grammar:2030:ex4:points:1":"「一番好きです」 means like the most.","grammar:2030:ex5:trans":"If you eat too much ice cream, your stomach hurts.","grammar:2030:ex5:structure":"アイスクリームを食べ過ぎると＋お腹が痛くなります","grammar:2030:ex5:words:0:zh":"ice cream","grammar:2030:ex5:words:0:pos":"noun","grammar:2030:ex5:words:1:zh":"object marker","grammar:2030:ex5:words:1:pos":"particle","grammar:2030:ex5:words:2:zh":"eat","grammar:2030:ex5:words:2:note":"たべ; the masu-form stem of 食べる","grammar:2030:ex5:words:2:pos":"verb","grammar:2030:ex5:words:3:zh":"excessively","grammar:2030:ex5:words:3:note":"すぎる; go past the limit","grammar:2030:ex5:words:3:pos":"auxiliary verb","grammar:2030:ex5:words:4:zh":"if","grammar:2030:ex5:words:4:pos":"particle","grammar:2030:ex5:words:5:zh":"stomach","grammar:2030:ex5:words:5:note":"おなか; stomach","grammar:2030:ex5:words:5:pos":"noun","grammar:2030:ex5:words:6:zh":"subject marker","grammar:2030:ex5:words:6:pos":"particle","grammar:2030:ex5:words:7:zh":"hurt / painful","grammar:2030:ex5:words:7:note":"いたく; the continuative form of 痛い","grammar:2030:ex5:words:7:pos":"adjective","grammar:2030:ex5:words:8:zh":"become","grammar:2030:ex5:words:8:pos":"verb","grammar:2030:ex5:words:9:zh":"polite","grammar:2030:ex5:words:9:pos":"auxiliary verb","grammar:2030:ex5:points:0":"「アイスクリームを食べ過ぎる」 means eating too much ice cream.","grammar:2030:ex5:points:1":"「adjective く＋なる」 shows a change of state."},"2031":{"example:2031:exzh":"This lottery ticket was a loser.","example:2031:exzh2":"His answer was wrong.","example:2031:exzh3":"It gets frustrating when you keep missing, doesn't it?","example:2031:exzh4":"I think there are more misses than hits.","example:2031:exzh5":"This product was a dud."},"2032":{"example:2032:exzh":"The population has been increasing recently.","example:2032:exzh2":"Work requests have increased.","example:2032:exzh3":"It's nice having more friends.","example:2032:exzh4":"It would be great if money increased, wouldn't it?","example:2032:exzh5":"If you exercise, your weight goes up.","grammar:2032:ex:trans":"The population is increasing these days.","grammar:2032:ex:structure":"〜が増えています","grammar:2032:ex:explain":"The core of this sentence is the intransitive verb 「増える」 plus 「〜ている」. 「増える」 is the intransitive verb to increase, and its subject is marked with 「が」; here nobody is increasing it, the population is growing on its own, which is why it takes 「が」. Distinguish it from the transitive 「増やす」 (to increase something): one is a natural change, the other is deliberately making something larger. 「増えています」 is the te-form plus 「います」, showing an ongoing state: it keeps increasing. 「最近」 is an adverb marking the time frame, and the sentence as a whole objectively describes a trend of population growth.","grammar:2032:ex:words:0:zh":"lately","grammar:2032:ex:words:0:note":"さいきん","grammar:2032:ex:words:0:pos":"noun","grammar:2032:ex:words:1:zh":"population","grammar:2032:ex:words:1:note":"じんこう","grammar:2032:ex:words:1:pos":"noun","grammar:2032:ex:words:2:zh":"(nominative)","grammar:2032:ex:words:2:pos":"particle","grammar:2032:ex:words:3:zh":"increasing","grammar:2032:ex:words:3:note":"ふえています","grammar:2032:ex:words:3:pos":"verb","grammar:2032:ex:points:0":"❗増える（ふえる）: to increase (intransitive verb); vs 増やす (transitive, to increase something); 人口が増える = the population grows.","grammar:2032:ex:points:1":"人口が増える: the population grows.","grammar:2032:ex2:trans":"Work requests have increased.","grammar:2032:ex2:structure":"〜が増えた","grammar:2032:ex2:words:0:zh":"work","grammar:2032:ex2:words:0:note":"しごと","grammar:2032:ex2:words:0:pos":"noun","grammar:2032:ex2:words:1:zh":"'s","grammar:2032:ex2:words:1:pos":"particle","grammar:2032:ex2:words:2:zh":"request, commission","grammar:2032:ex2:words:2:note":"いらい","grammar:2032:ex2:words:2:pos":"noun","grammar:2032:ex2:words:3:zh":"(nominative)","grammar:2032:ex2:words:3:pos":"particle","grammar:2032:ex2:words:4:zh":"increased","grammar:2032:ex2:words:4:note":"ふえた","grammar:2032:ex2:words:4:pos":"verb","grammar:2032:ex2:points:0":"❗依頼: a request, a commission; 依頼が増える = more jobs come in.","grammar:2032:ex2:points:1":"依頼が増える: requests increase.","grammar:2032:ex3:trans":"I'm happy to have more friends.","grammar:2032:ex3:structure":"〜が増えて楽しいです","grammar:2032:ex3:words:0:zh":"friend","grammar:2032:ex3:words:0:note":"ともだち","grammar:2032:ex3:words:0:pos":"noun","grammar:2032:ex3:words:1:zh":"(nominative)","grammar:2032:ex3:words:1:pos":"particle","grammar:2032:ex3:words:2:zh":"increase","grammar:2032:ex3:words:2:note":"ふえて","grammar:2032:ex3:words:2:pos":"verb","grammar:2032:ex3:words:3:zh":"happy","grammar:2032:ex3:words:3:note":"たのしい","grammar:2032:ex3:words:3:pos":"adjective","grammar:2032:ex3:words:4:zh":"(polite form)","grammar:2032:ex3:words:4:pos":"copula","grammar:2032:ex3:points:0":"❗友達が増える: to have more friends; 〜て = because … (te-form for cause).","grammar:2032:ex3:points:1":"友達が増える: friends increase.","grammar:2032:ex4:trans":"It would be nice if the money increased.","grammar:2032:ex4:structure":"〜が増えると良いですね","grammar:2032:ex4:words:0:zh":"money","grammar:2032:ex4:words:0:note":"おかね","grammar:2032:ex4:words:0:pos":"noun","grammar:2032:ex4:words:1:zh":"(nominative)","grammar:2032:ex4:words:1:pos":"particle","grammar:2032:ex4:words:2:zh":"increase","grammar:2032:ex4:words:2:note":"ふえる","grammar:2032:ex4:words:2:pos":"verb","grammar:2032:ex4:words:3:zh":"(as soon as…)","grammar:2032:ex4:words:3:pos":"particle","grammar:2032:ex4:words:4:zh":"good","grammar:2032:ex4:words:4:note":"いい","grammar:2032:ex4:words:4:pos":"adjective","grammar:2032:ex4:words:5:zh":"(polite form)","grammar:2032:ex4:words:5:pos":"copula","grammar:2032:ex4:words:6:zh":"(tone)","grammar:2032:ex4:words:6:pos":"particle","grammar:2032:ex4:points:0":"❗〜と良い: it would be good if …; お金が増える = money increases.","grammar:2032:ex4:points:1":"増えると良い: it would be nice if it increased.","grammar:2032:ex5:trans":"If you exercise, your weight increases.","grammar:2032:ex5:structure":"〜をすると〜が増えます","grammar:2032:ex5:words:0:zh":"exercise","grammar:2032:ex5:words:0:note":"うんどう","grammar:2032:ex5:words:0:pos":"noun","grammar:2032:ex5:words:1:zh":"(object marker)","grammar:2032:ex5:words:1:pos":"particle","grammar:2032:ex5:words:2:zh":"if you do","grammar:2032:ex5:words:2:pos":"verb","grammar:2032:ex5:words:3:zh":"body weight","grammar:2032:ex5:words:3:note":"たいじゅう","grammar:2032:ex5:words:3:pos":"noun","grammar:2032:ex5:words:4:zh":"(nominative)","grammar:2032:ex5:words:4:pos":"particle","grammar:2032:ex5:words:5:zh":"increase","grammar:2032:ex5:words:5:note":"ふえます","grammar:2032:ex5:words:5:pos":"verb","grammar:2032:ex5:points:0":"❗〜すると: whenever …, …; 体重が増える = body weight increases (the causal link in this sentence is questionable).","grammar:2032:ex5:points:1":"体重が増える: to gain weight."},"2033":{"example:2033:exzh":"He broke a bone playing soccer.","example:2033:exzh2":"Treating a broken bone takes time.","example:2033:exzh3":"I broke a bone when I was young.","example:2033:exzh4":"The broken part still hurts.","example:2033:exzh5":"Broken bones often happen during exercise."},"2034":{"example:2034:exzh":"He won the tournament back to back.","example:2034:exzh2":"I watch the drama series every week.","example:2034:exzh3":"This problem keeps occurring continuously.","example:2034:exzh4":"I worked for two hours straight.","example:2034:exzh5":"She made mistakes five times in a row."},"2035":{"example:2035:exzh":"I loaded the luggage into the car.","example:2035:exzh2":"The car was loaded onto the boat and taken to the island.","example:2035:exzh3":"I'll load this book and the important documents into the car.","example:2035:exzh4":"I'm loading lots of cargo onto the truck.","example:2035:exzh5":"The driver is good at loading heavy luggage."},"2036":{"example:2036:exzh":"He is trying to escape from responsibility.","example:2036:exzh2":"You can't escape the problem.","example:2036:exzh3":"She tried to escape from that truth.","example:2036:exzh4":"Some fates cannot be escaped.","example:2036:exzh5":"I want to escape from a difficult situation."},"2037":{"example:2037:exzh":"I registered a new account.","example:2037:exzh2":"I applied for a service that requires registration.","example:2037:exzh3":"He enrolled at a university.","example:2037:exzh4":"You can register for this app for free.","example:2037:exzh5":"The registration deadline is close, so I need to hurry."},"2038":{"example:2038:exzh":"Please look at that page once more.","example:2038:exzh2":"Please turn the page of this book.","example:2038:exzh3":"The web page is loading.","example:2038:exzh4":"She wrote a comment on the page.","example:2038:exzh5":"We redesigned our homepage.","grammar:2038:ex:trans":"Please look at that page one more time.","grammar:2038:ex:structure":"そのページをもう一度見てください","grammar:2038:ex:explain":"The core of this sentence is 「〜てください」, which makes a request. 「見てください」 is formed from the te-form of 「見る」, 「見て」, plus 「ください」, politely asking the other person to look. 「もう一度」 is the adverb meaning one more time, modifying the action to show repetition. The 「を」 in 「そのページを」 marks what is being looked at. 「てください」 is the most common request pattern in everyday speech; you simply attach it to a verb's te-form, and it is far more polite than the imperative, making it suitable for asking someone to do something in most polite situations.","grammar:2038:ex:words:0:zh":"that","grammar:2038:ex:words:0:pos":"pre-noun adjectival","grammar:2038:ex:words:1:zh":"page","grammar:2038:ex:words:1:note":"loanword","grammar:2038:ex:words:1:pos":"noun","grammar:2038:ex:words:2:zh":"(object marker)","grammar:2038:ex:words:2:pos":"particle","grammar:2038:ex:words:3:zh":"one more time","grammar:2038:ex:words:3:note":"もういちど","grammar:2038:ex:words:3:pos":"adverb","grammar:2038:ex:words:4:zh":"look","grammar:2038:ex:words:4:note":"みて","grammar:2038:ex:words:4:pos":"verb","grammar:2038:ex:words:5:zh":"please","grammar:2038:ex:words:5:pos":"auxiliary verb","grammar:2038:ex:points:0":"❗ページ: page, page (page); もう一度 = one more time.","grammar:2038:ex:points:1":"ページ: page.","grammar:2038:ex2:trans":"Please turn the page of this book.","grammar:2038:ex2:structure":"本のページをめくってください","grammar:2038:ex2:words:0:zh":"this","grammar:2038:ex2:words:0:pos":"pre-noun adjectival","grammar:2038:ex2:words:1:zh":"book","grammar:2038:ex2:words:1:note":"ほん","grammar:2038:ex2:words:1:pos":"noun","grammar:2038:ex2:words:2:zh":"'s","grammar:2038:ex2:words:2:pos":"particle","grammar:2038:ex2:words:3:zh":"page","grammar:2038:ex2:words:3:note":"loanword","grammar:2038:ex2:words:3:pos":"noun","grammar:2038:ex2:words:4:zh":"(object marker)","grammar:2038:ex2:words:4:pos":"particle","grammar:2038:ex2:words:5:zh":"turn","grammar:2038:ex2:words:5:note":"めくって","grammar:2038:ex2:words:5:pos":"verb","grammar:2038:ex2:words:6:zh":"please","grammar:2038:ex2:words:6:pos":"auxiliary verb","grammar:2038:ex2:points:0":"❗ページをめくる: to turn a page (めくる = to turn, to flip).","grammar:2038:ex2:points:1":"ページをめくる: turn a page.","grammar:2038:ex3:trans":"The web page is loading.","grammar:2038:ex3:structure":"ウェブページが読み込まれています","grammar:2038:ex3:words:0:zh":"web page","grammar:2038:ex3:words:0:note":"loanword","grammar:2038:ex3:words:0:pos":"noun","grammar:2038:ex3:words:1:zh":"(nominative)","grammar:2038:ex3:words:1:pos":"particle","grammar:2038:ex3:words:2:zh":"is being loaded","grammar:2038:ex3:words:2:note":"よみこまれています","grammar:2038:ex3:words:2:pos":"verb","grammar:2038:ex3:points:0":"❗ウェブページ: web page (web + page); 読み込まれる = to be loaded (passive form).","grammar:2038:ex3:points:1":"ウェブページ: web page.","grammar:2038:ex4:trans":"She wrote a comment on the page.","grammar:2038:ex4:structure":"ページにコメントを書いた","grammar:2038:ex4:words:0:zh":"she","grammar:2038:ex4:words:0:note":"かのじょ","grammar:2038:ex4:words:0:pos":"pronoun","grammar:2038:ex4:words:1:zh":"(topic)","grammar:2038:ex4:words:1:pos":"particle","grammar:2038:ex4:words:2:zh":"page","grammar:2038:ex4:words:2:note":"loanword","grammar:2038:ex4:words:2:pos":"noun","grammar:2038:ex4:words:3:zh":"(the destination point)","grammar:2038:ex4:words:3:pos":"particle","grammar:2038:ex4:words:4:zh":"comment","grammar:2038:ex4:words:4:note":"loanword","grammar:2038:ex4:words:4:pos":"noun","grammar:2038:ex4:words:5:zh":"(object marker)","grammar:2038:ex4:words:5:pos":"particle","grammar:2038:ex4:words:6:zh":"wrote","grammar:2038:ex4:words:6:note":"かいた","grammar:2038:ex4:words:6:pos":"verb","grammar:2038:ex4:points:0":"❗コメントを書く: to leave a comment, to write a comment.","grammar:2038:ex4:points:1":"コメントを書く: leave a comment.","grammar:2038:ex5:trans":"We've renewed our homepage.","grammar:2038:ex5:structure":"ホームページをリニューアルしました","grammar:2038:ex5:words:0:zh":"homepage","grammar:2038:ex5:words:0:note":"loanword","grammar:2038:ex5:words:0:pos":"noun","grammar:2038:ex5:words:1:zh":"(object marker)","grammar:2038:ex5:words:1:pos":"particle","grammar:2038:ex5:words:2:zh":"renewed","grammar:2038:ex5:words:2:pos":"verb","grammar:2038:ex5:points:0":"❗ホームページ: website homepage, official site (homepage); リニューアル = revamp, renewal (renewal).","grammar:2038:ex5:points:1":"ホームページ: official website.","exam:2038:zh":"In this book, the front and back of one sheet of paper count as two pages.","exam:2038:why":"「ページ」 counts one side of a page, so one sheet of paper has two pages. 「枚」 counts sheets of paper, and one sheet is still 「一枚」."},"2039":{"example:2039:exzh":"My computer is old.","example:2039:exzh2":"I'm playing a game on the computer.","example:2039:exzh3":"That computer is easy to use.","example:2039:exzh4":"I bought a new computer.","example:2039:exzh5":"The computer isn't working well.","grammar:2039:ex:trans":"My computer is old.","grammar:2039:ex:structure":"私のパソコンは古いです","grammar:2039:ex:explain":"This sentence is a predicate sentence with an i-adjective. The dictionary form 「古い」 ends in 「い」 and is a pure i-adjective meaning old; adding 「です」 at the end gives 「古いです」, where 「です」 only adds politeness without changing the meaning. 「私のパソコン」 joins with 「の」 to mean my computer, and 「は」 marks it as the topic. The whole sentence states a quality of the computer: that it is old. Note that i-adjectives differ from na-adjectives: an i-adjective can take 「です」 directly, unlike a na-adjective, which drops 「な」 when it acts as a predicate; the two follow different conjugation rules.","grammar:2039:ex:words:0:zh":"I","grammar:2039:ex:words:0:note":"わたし","grammar:2039:ex:words:0:pos":"pronoun","grammar:2039:ex:words:1:zh":"'s","grammar:2039:ex:words:1:pos":"particle","grammar:2039:ex:words:2:zh":"computer","grammar:2039:ex:words:2:note":"loanword","grammar:2039:ex:words:2:pos":"noun","grammar:2039:ex:words:3:zh":"(topic)","grammar:2039:ex:words:3:pos":"particle","grammar:2039:ex:words:4:zh":"old","grammar:2039:ex:words:4:note":"ふるい","grammar:2039:ex:words:4:pos":"adjective","grammar:2039:ex:words:5:zh":"(polite form)","grammar:2039:ex:words:5:pos":"copula","grammar:2039:ex:points:0":"❗パソコン: personal computer (a Japanese abbreviation of personal computer).","grammar:2039:ex:points:1":"パソコン: computer.","grammar:2039:ex2:trans":"I'm playing a game on the computer.","grammar:2039:ex2:structure":"パソコンでゲームをしています","grammar:2039:ex2:words:0:zh":"computer","grammar:2039:ex2:words:0:note":"loanword","grammar:2039:ex2:words:0:pos":"noun","grammar:2039:ex2:words:1:zh":"(means)","grammar:2039:ex2:words:1:pos":"particle","grammar:2039:ex2:words:2:zh":"game","grammar:2039:ex2:words:2:note":"loanword","grammar:2039:ex2:words:2:pos":"noun","grammar:2039:ex2:words:3:zh":"(object marker)","grammar:2039:ex2:words:3:pos":"particle","grammar:2039:ex2:words:4:zh":"is doing","grammar:2039:ex2:words:4:pos":"verb","grammar:2039:ex2:points:0":"❗❓パソコンで = with a computer (で marks the means); ゲームをする = to play video games.","grammar:2039:ex2:points:1":"パソコンで: with a computer.","grammar:2039:ex3:trans":"That computer is easy to use.","grammar:2039:ex3:structure":"そのパソコンは使いやすいです","grammar:2039:ex3:words:0:zh":"that","grammar:2039:ex3:words:0:pos":"pre-noun adjectival","grammar:2039:ex3:words:1:zh":"computer","grammar:2039:ex3:words:1:note":"loanword","grammar:2039:ex3:words:1:pos":"noun","grammar:2039:ex3:words:2:zh":"(topic)","grammar:2039:ex3:words:2:pos":"particle","grammar:2039:ex3:words:3:zh":"easy to use","grammar:2039:ex3:words:3:note":"つかいやすい","grammar:2039:ex3:words:3:pos":"verb","grammar:2039:ex3:words:4:zh":"(polite form)","grammar:2039:ex3:words:4:pos":"copula","grammar:2039:ex3:points:0":"❗〜やすい: easy to … (使いやすい = easy to use).","grammar:2039:ex3:points:1":"使いやすい: easy to use.","grammar:2039:ex4:trans":"I bought a new computer.","grammar:2039:ex4:structure":"新しいパソコンを買いました","grammar:2039:ex4:words:0:zh":"new","grammar:2039:ex4:words:0:note":"あたらしい","grammar:2039:ex4:words:0:pos":"adjective","grammar:2039:ex4:words:1:zh":"computer","grammar:2039:ex4:words:1:note":"loanword","grammar:2039:ex4:words:1:pos":"noun","grammar:2039:ex4:words:2:zh":"(object marker)","grammar:2039:ex4:words:2:pos":"particle","grammar:2039:ex4:words:3:zh":"bought","grammar:2039:ex4:words:3:note":"かいました","grammar:2039:ex4:words:3:pos":"verb","grammar:2039:ex4:points:0":"❗新しいパソコン: a new computer.","grammar:2039:ex4:points:1":"新しいパソコン: a new computer.","grammar:2039:ex5:trans":"The computer isn't working well.","grammar:2039:ex5:structure":"パソコンの調子が悪い","grammar:2039:ex5:words:0:zh":"computer","grammar:2039:ex5:words:0:note":"loanword","grammar:2039:ex5:words:0:pos":"noun","grammar:2039:ex5:words:1:zh":"'s","grammar:2039:ex5:words:1:pos":"particle","grammar:2039:ex5:words:2:zh":"situation","grammar:2039:ex5:words:2:note":"ちょうし","grammar:2039:ex5:words:2:pos":"noun","grammar:2039:ex5:words:3:zh":"(nominative)","grammar:2039:ex5:words:3:pos":"particle","grammar:2039:ex5:words:4:zh":"bad / not good","grammar:2039:ex5:words:4:note":"わるい","grammar:2039:ex5:words:4:pos":"adjective","grammar:2039:ex5:points:0":"❗調子が悪い: in bad shape, not going well (a set expression; 調子 = condition).","grammar:2039:ex5:points:1":"調子が悪い: to be in poor condition."},"2040":{"example:2040:exzh":"I have a thousand yen.","example:2040:exzh2":"A thousand people gathered.","example:2040:exzh3":"It has a thousand years of history.","example:2040:exzh4":"He tried a thousand times.","example:2040:exzh5":"There is origami of a thousand cranes.","grammar:2040:ex:trans":"I have a thousand yen.","grammar:2040:ex:structure":"千円を持っています","grammar:2040:ex:explain":"The core of this sentence is 「〜ている」, which expresses a state of possession. 「持っています」 is the te-form of 「持つ」 plus 「います」, but here it does not mean the action of holding is in progress; it expresses the continuing state of owning or possessing, equivalent to have a thousand yen. For verbs like 「持つ」, 「ている」 usually indicates a state rather than an ongoing action. The 「を」 in 「千円を」 marks what is possessed. Note that 「千」 is usually not preceded by 「一」; saying 「千円」 directly means one thousand yen, which is the convention for numbers.","grammar:2040:ex:words:0:zh":"a thousand yen","grammar:2040:ex:words:0:note":"せんえん","grammar:2040:ex:words:0:pos":"noun","grammar:2040:ex:words:1:zh":"(object marker)","grammar:2040:ex:words:1:pos":"particle","grammar:2040:ex:words:2:zh":"to have","grammar:2040:ex:words:2:note":"もっています","grammar:2040:ex:words:2:pos":"verb","grammar:2040:ex:points:0":"❗千 (せん): one thousand; 千円 = one thousand yen (「千」 is usually not preceded by 「一」).","grammar:2040:ex:points:1":"千: thousand.","grammar:2040:ex2:trans":"A thousand people gathered.","grammar:2040:ex2:structure":"numeral ＋ 人が集まった","grammar:2040:ex2:words:0:zh":"one thousand","grammar:2040:ex2:words:0:note":"せん","grammar:2040:ex2:words:0:pos":"numeral","grammar:2040:ex2:words:1:zh":"person","grammar:2040:ex2:words:1:note":"にん","grammar:2040:ex2:words:1:pos":"suffix","grammar:2040:ex2:words:2:zh":"(subject)","grammar:2040:ex2:words:2:pos":"particle","grammar:2040:ex2:words:3:zh":"gathered","grammar:2040:ex2:words:3:note":"atsumatta; ta-form of 集まる","grammar:2040:ex2:words:3:pos":"verb","grammar:2040:ex2:points:0":"「千人」 is read 「せんにん」: in Japanese, one thousand is usually said simply as 「千」, without 「一」 (「一千」 is used only for emphasis or in written accounts).","grammar:2040:ex2:points:1":"「集まった」 is the past form of the intransitive verb 「集まる」, and the subject takes 「が」; the transitive verb is 「集める」.","grammar:2040:ex3:trans":"It has a thousand years of history.","grammar:2040:ex3:structure":"千年の歴史があります","grammar:2040:ex3:words:0:zh":"a thousand years","grammar:2040:ex3:words:0:note":"せんねん","grammar:2040:ex3:words:0:pos":"noun","grammar:2040:ex3:words:1:zh":"'s","grammar:2040:ex3:words:1:pos":"particle","grammar:2040:ex3:words:2:zh":"history","grammar:2040:ex3:words:2:note":"れきし","grammar:2040:ex3:words:2:pos":"noun","grammar:2040:ex3:words:3:zh":"(nominative)","grammar:2040:ex3:words:3:pos":"particle","grammar:2040:ex3:words:4:zh":"there is / are","grammar:2040:ex3:words:4:pos":"verb","grammar:2040:ex3:points:0":"❗千年 (せんねん): one thousand years; 千年の歴史 = a thousand years of history.","grammar:2040:ex3:points:1":"千年: a thousand years.","grammar:2040:ex4:trans":"He tried a thousand times.","grammar:2040:ex4:structure":"彼は千回試みた","grammar:2040:ex4:words:0:zh":"he","grammar:2040:ex4:words:0:note":"かれ","grammar:2040:ex4:words:0:pos":"pronoun","grammar:2040:ex4:words:1:zh":"(topic)","grammar:2040:ex4:words:1:pos":"particle","grammar:2040:ex4:words:2:zh":"a thousand times","grammar:2040:ex4:words:2:note":"せんかい","grammar:2040:ex4:words:2:pos":"noun","grammar:2040:ex4:words:3:zh":"Tried","grammar:2040:ex4:words:3:note":"こころみた","grammar:2040:ex4:words:3:pos":"verb","grammar:2040:ex4:points:0":"❗千回 (せんかい): a thousand times; 試みる = to try (more written than 「試す」).","grammar:2040:ex4:points:1":"千回: a thousand times.","grammar:2040:ex5:trans":"There is a thousand-crane origami.","grammar:2040:ex5:structure":"千羽の鶴の折り紙があります","grammar:2040:ex5:words:0:zh":"a thousand (birds)","grammar:2040:ex5:words:0:note":"せんば","grammar:2040:ex5:words:0:pos":"noun","grammar:2040:ex5:words:1:zh":"'s","grammar:2040:ex5:words:1:pos":"particle","grammar:2040:ex5:words:2:zh":"crane","grammar:2040:ex5:words:2:note":"つる","grammar:2040:ex5:words:2:pos":"noun","grammar:2040:ex5:words:3:zh":"'s","grammar:2040:ex5:words:3:pos":"particle","grammar:2040:ex5:words:4:zh":"origami","grammar:2040:ex5:words:4:note":"おりがみ","grammar:2040:ex5:words:4:pos":"noun","grammar:2040:ex5:words:5:zh":"(nominative)","grammar:2040:ex5:words:5:pos":"particle","grammar:2040:ex5:words:6:zh":"there is / are","grammar:2040:ex5:words:6:pos":"verb","exam:2040:zh":"If you buy ten 100-yen stamps, the total is 1,000 yen.","exam:2040:why":"A hundred times ten is a thousand, so 「千」 is the answer. 「百」 is just the price of one stamp."},"2041":{"example:2041:exzh":"I planted flowers in the garden.","example:2041:exzh2":"The children are playing in the garden.","example:2041:exzh3":"He is taking care of the garden.","example:2041:exzh4":"This garden is very beautiful.","example:2041:exzh5":"We had a barbecue in the garden.","grammar:2041:ex:trans":"I planted flowers in the garden.","grammar:2041:ex:structure":"庭に花を植えました","grammar:2041:ex:explain":"The core of this sentence is the two-particle pattern 「〜に〜を植える」. 「植える」 is the transitive verb to plant; 「に」 marks 「庭」, where the planting ends up, indicating the destination, while 「を」 marks 「花」, the thing being planted. 「植えました」 is the polite past form. The sentence planted flowers in the garden divides where with 「に」 and what with 「を」 clearly. The 「に」 marking the spot where the result of an action lands is different from 「で」, which marks where an action takes place; this sentence stresses the spot where the flowers end up, so it uses 「に」.","grammar:2041:ex:words:0:zh":"garden","grammar:2041:ex:words:0:note":"にわ","grammar:2041:ex:words:0:pos":"noun","grammar:2041:ex:words:1:zh":"(the destination point)","grammar:2041:ex:words:1:pos":"particle","grammar:2041:ex:words:2:zh":"flowers","grammar:2041:ex:words:2:note":"はな","grammar:2041:ex:words:2:pos":"noun","grammar:2041:ex:words:3:zh":"(object marker)","grammar:2041:ex:words:3:pos":"particle","grammar:2041:ex:words:4:zh":"planted","grammar:2041:ex:words:4:note":"うえました","grammar:2041:ex:words:4:pos":"verb","grammar:2041:ex:points:0":"❗庭 (にわ): garden, yard; 庭に植える = to plant in the garden.","grammar:2041:ex:points:1":"庭: garden.","grammar:2041:ex2:trans":"The children are playing in the garden.","grammar:2041:ex2:structure":"庭で子供たちが遊んでいます","grammar:2041:ex2:words:0:zh":"garden","grammar:2041:ex2:words:0:note":"にわ","grammar:2041:ex2:words:0:pos":"noun","grammar:2041:ex2:words:1:zh":"(place)","grammar:2041:ex2:words:1:pos":"particle","grammar:2041:ex2:words:2:zh":"children","grammar:2041:ex2:words:2:note":"こどもたち","grammar:2041:ex2:words:2:pos":"noun","grammar:2041:ex2:words:3:zh":"(nominative)","grammar:2041:ex2:words:3:pos":"particle","grammar:2041:ex2:words:4:zh":"are playing","grammar:2041:ex2:words:4:note":"あそんでいます","grammar:2041:ex2:words:4:pos":"verb","grammar:2041:ex2:points:0":"❗❓庭で = in the garden (で marks where the action happens); vs 庭に (existence / destination).","grammar:2041:ex2:points:1":"庭で遊ぶ: play in the garden.","grammar:2041:ex3:trans":"He's taking care of the garden.","grammar:2041:ex3:structure":"庭の手入れをしています","grammar:2041:ex3:words:0:zh":"he","grammar:2041:ex3:words:0:note":"かれ","grammar:2041:ex3:words:0:pos":"pronoun","grammar:2041:ex3:words:1:zh":"(topic)","grammar:2041:ex3:words:1:pos":"particle","grammar:2041:ex3:words:2:zh":"garden","grammar:2041:ex3:words:2:note":"にわ","grammar:2041:ex3:words:2:pos":"noun","grammar:2041:ex3:words:3:zh":"'s","grammar:2041:ex3:words:3:pos":"particle","grammar:2041:ex3:words:4:zh":"taking care of","grammar:2041:ex3:words:4:note":"ていれ","grammar:2041:ex3:words:4:pos":"noun","grammar:2041:ex3:words:5:zh":"(object marker)","grammar:2041:ex3:words:5:pos":"particle","grammar:2041:ex3:words:6:zh":"is doing","grammar:2041:ex3:words:6:pos":"verb","grammar:2041:ex3:points:0":"❗手入れ: upkeep, tidying; 庭の手入れ = tending the garden.","grammar:2041:ex3:points:1":"手入れ: tidying up.","grammar:2041:ex4:trans":"This garden is very beautiful.","grammar:2041:ex4:structure":"この庭はとても美しいです","grammar:2041:ex4:words:0:zh":"this","grammar:2041:ex4:words:0:pos":"pre-noun adjectival","grammar:2041:ex4:words:1:zh":"garden","grammar:2041:ex4:words:1:note":"にわ","grammar:2041:ex4:words:1:pos":"noun","grammar:2041:ex4:words:2:zh":"(topic)","grammar:2041:ex4:words:2:pos":"particle","grammar:2041:ex4:words:3:zh":"extremely","grammar:2041:ex4:words:3:pos":"adverb","grammar:2041:ex4:words:4:zh":"beautiful","grammar:2041:ex4:words:4:note":"うつくしい","grammar:2041:ex4:words:4:pos":"adjective","grammar:2041:ex4:words:5:zh":"(polite form)","grammar:2041:ex4:words:5:pos":"copula","grammar:2041:ex4:points:0":"❗美しい庭: a beautiful garden.","grammar:2041:ex4:points:1":"美しい庭: a beautiful garden.","grammar:2041:ex5:trans":"We had a barbecue in the garden.","grammar:2041:ex5:structure":"庭でバーベキューをしました","grammar:2041:ex5:words:0:zh":"garden","grammar:2041:ex5:words:0:note":"にわ","grammar:2041:ex5:words:0:pos":"noun","grammar:2041:ex5:words:1:zh":"(place)","grammar:2041:ex5:words:1:pos":"particle","grammar:2041:ex5:words:2:zh":"Barbecue","grammar:2041:ex5:words:2:note":"loanword","grammar:2041:ex5:words:2:pos":"noun","grammar:2041:ex5:words:3:zh":"(object marker)","grammar:2041:ex5:words:3:pos":"particle","grammar:2041:ex5:words:4:zh":"did","grammar:2041:ex5:words:4:pos":"verb","grammar:2041:ex5:points:0":"❗バーベキュー: barbecue (barbecue, shortened to 「BBQ」); ❓庭で = in the garden.","grammar:2041:ex5:points:1":"バーベキュー: barbecue.","exam:2041:zh":"My yard has trees and flowers, and I play with my dog there.","exam:2041:why":"A garden is the outdoor space beside a house where you can plant trees and flowers and play. The entryway is just a doorway, which doesn't fit the description of a space with trees where people play."},"2042":{"example:2042:exzh":"His behavior is a nuisance.","example:2042:exzh2":"I'm very sorry for the trouble I caused.","example:2042:exzh3":"Please don't do things that cause trouble.","example:2042:exzh4":"They are bothering the customers around them.","example:2042:exzh5":"I don't want to cause trouble."},"2043":{"example:2043:exzh":"I think this proposal is very good.","example:2043:exzh2":"I'm thinking about a new business plan.","example:2043:exzh3":"Everyone supports his proposal.","example:2043:exzh4":"Is there a problem with this proposal?","example:2043:exzh5":"I want them to come up with a better idea."},"2044":{"example:2044:exzh":"You must not burn this wood.","example:2044:exzh2":"I'm burning paper in the bonfire.","example:2044:exzh3":"He is burning trash.","example:2044:exzh4":"Burning is prohibited by law.","example:2044:exzh5":"I burn a fire to stay warm."},"2046":{"example:2046:exzh":"This car's speed is high.","example:2046:exzh2":"Please don't drive too fast.","example:2046:exzh3":"He was caught for a speeding violation.","example:2046:exzh4":"It's used when speed is needed.","example:2046:exzh5":"Measure the speed."},"2047":{"example:2047:exzh":"A lack of funds is a problem.","example:2047:exzh2":"There is a food shortage.","example:2047:exzh3":"There is a shortage of workers.","example:2047:exzh4":"I'll think about ways to resolve the shortage.","example:2047:exzh5":"I think the lack of education is a problem."},"2048":{"example:2048:exzh":"Please open the door.","example:2048:exzh2":"The gate of the house is very big.","example:2048:exzh3":"I'm waiting in front of the gate.","example:2048:exzh4":"He closed the gate.","example:2048:exzh5":"I heard the sound of the gate.","grammar:2048:ex:trans":"Please open the door.","grammar:2048:ex:structure":"門を開けてください","grammar:2048:ex:explain":"The core of this sentence is 「〜てください」, which makes a request, and the verb is transitive. 「開けてください」 is formed from the te-form of the transitive verb 「開ける」 (to open) plus 「ください」, politely asking the other person to open the gate. The 「を」 in 「門を」 marks what is being opened. Distinguish it from the intransitive 「開く」 (あく), where the gate opens by itself: 「開ける」 is the transitive action of a person opening something. 「門」 usually refers to the gate of a residence or temple; for room doors, 「ドア」 or 「戸」 is more common. The whole sentence is a polite request.","grammar:2048:ex:words:0:zh":"door","grammar:2048:ex:words:0:note":"もん","grammar:2048:ex:words:0:pos":"noun","grammar:2048:ex:words:1:zh":"(object marker)","grammar:2048:ex:words:1:pos":"particle","grammar:2048:ex:words:2:zh":"open","grammar:2048:ex:words:2:note":"あけて","grammar:2048:ex:words:2:pos":"verb","grammar:2048:ex:words:3:zh":"please","grammar:2048:ex:words:3:pos":"auxiliary verb","grammar:2048:ex:points:0":"❗門 (もん): gate, door (usually the gate of a residence or temple; for room doors, 「ドア」 or 「戸」 is used).","grammar:2048:ex:points:1":"門: gate.","grammar:2048:ex2:trans":"The gate of the house is very big.","grammar:2048:ex2:structure":"家の門はとても大きいです","grammar:2048:ex2:words:0:zh":"house","grammar:2048:ex2:words:0:note":"いえ","grammar:2048:ex2:words:0:pos":"noun","grammar:2048:ex2:words:1:zh":"'s","grammar:2048:ex2:words:1:pos":"particle","grammar:2048:ex2:words:2:zh":"door","grammar:2048:ex2:words:2:note":"もん","grammar:2048:ex2:words:2:pos":"noun","grammar:2048:ex2:words:3:zh":"(topic)","grammar:2048:ex2:words:3:pos":"particle","grammar:2048:ex2:words:4:zh":"extremely","grammar:2048:ex2:words:4:pos":"adverb","grammar:2048:ex2:words:5:zh":"big","grammar:2048:ex2:words:5:note":"おおきい","grammar:2048:ex2:words:5:pos":"adjective","grammar:2048:ex2:words:6:zh":"(polite form)","grammar:2048:ex2:words:6:pos":"copula","grammar:2048:ex2:points:0":"❗家の門: the gate of a house.","grammar:2048:ex2:points:1":"家の門: house gate.","grammar:2048:ex3:trans":"I'm waiting in front of the gate.","grammar:2048:ex3:structure":"門の前で待っています","grammar:2048:ex3:words:0:zh":"door","grammar:2048:ex3:words:0:note":"もん","grammar:2048:ex3:words:0:pos":"noun","grammar:2048:ex3:words:1:zh":"'s","grammar:2048:ex3:words:1:pos":"particle","grammar:2048:ex3:words:2:zh":"front","grammar:2048:ex3:words:2:note":"まえ","grammar:2048:ex3:words:2:pos":"noun","grammar:2048:ex3:words:3:zh":"(place)","grammar:2048:ex3:words:3:pos":"particle","grammar:2048:ex3:words:4:zh":"waiting for","grammar:2048:ex3:words:4:note":"まっています","grammar:2048:ex3:words:4:pos":"verb","grammar:2048:ex3:points:0":"❗❓門の前で = in front of the gate (で marks place).","grammar:2048:ex3:points:1":"門の前: in front of the gate.","grammar:2048:ex4:trans":"He closed the gate.","grammar:2048:ex4:structure":"彼は門を閉めた","grammar:2048:ex4:words:0:zh":"he","grammar:2048:ex4:words:0:note":"かれ","grammar:2048:ex4:words:0:pos":"pronoun","grammar:2048:ex4:words:1:zh":"(topic)","grammar:2048:ex4:words:1:pos":"particle","grammar:2048:ex4:words:2:zh":"door","grammar:2048:ex4:words:2:note":"もん","grammar:2048:ex4:words:2:pos":"noun","grammar:2048:ex4:words:3:zh":"(object marker)","grammar:2048:ex4:words:3:pos":"particle","grammar:2048:ex4:words:4:zh":"closed","grammar:2048:ex4:words:4:note":"しめた","grammar:2048:ex4:words:4:pos":"verb","grammar:2048:ex4:points:0":"❗門を閉める: to close the gate (閉める is a transitive verb).","grammar:2048:ex4:points:1":"門を閉める: close the gate.","grammar:2048:ex5:trans":"I heard the sound of the gate.","grammar:2048:ex5:structure":"門の音が聞こえた","grammar:2048:ex5:words:0:zh":"door","grammar:2048:ex5:words:0:note":"もん","grammar:2048:ex5:words:0:pos":"noun","grammar:2048:ex5:words:1:zh":"'s","grammar:2048:ex5:words:1:pos":"particle","grammar:2048:ex5:words:2:zh":"voice","grammar:2048:ex5:words:2:note":"おと","grammar:2048:ex5:words:2:pos":"noun","grammar:2048:ex5:words:3:zh":"(nominative)","grammar:2048:ex5:words:3:pos":"particle","grammar:2048:ex5:words:4:zh":"heard","grammar:2048:ex5:words:4:note":"きこえた","grammar:2048:ex5:words:4:pos":"verb","grammar:2048:ex5:points:0":"❗音が聞こえる: to hear a sound (naturally) (聞こえる is an intransitive verb).","grammar:2048:ex5:points:1":"音が聞こえる: hear a sound."},"2049":{"example:2049:exzh":"He seized the chance.","example:2049:exzh2":"It's important to capture that moment.","example:2049:exzh3":"Catching animals is difficult.","example:2049:exzh4":"I captured the beautiful scenery in a photo.","example:2049:exzh5":"She has a talent for capturing emotions."},"2050":{"example:2050:exzh":"He woke up at six in the morning.","example:2050:exzh2":"I shook off my sleepiness with cold water.","example:2050:exzh3":"The child woke up several times during the night.","example:2050:exzh4":"I was woken up by the sound of the phone.","example:2050:exzh5":"I use an alarm clock to wake myself up."},"2051":{"example:2051:exzh":"He said he wants to become a doctor.","example:2051:exzh2":"It will be summer soon.","example:2051:exzh3":"She graduated from university and became a teacher.","example:2051:exzh4":"When you go to Japan, you'll be able to experience the culture.","example:2051:exzh5":"My older brother turned twenty last year.","grammar:2051:ex:trans":"He said he wanted to become a doctor.","grammar:2051:ex:structure":"〔〜になりたい〕＋と＋言った。「〜になりたい」 = to want to become…; 「と言った」 quotes it.","grammar:2051:ex:explain":"The core of this sentence is 「〜になりたい」 plus the quotation 「〜と言った」. In 「医者になる」, 「に」 marks the result of the change (becoming a doctor); verbs of change like 「なる」 habitually take 「に」. 「なりたい」 is the masu-stem of 「なる」 plus 「たい」, expressing the wish to become. After that, 「と言った」 wraps the wish in the quotation particle 「と」 and adds the past form of 「言う」, meaning he said…. The whole sentence reports someone else's wish; 「〜たいと言った」 is a common structure for quoting another person's thoughts.","grammar:2051:ex:words:0:zh":"he","grammar:2051:ex:words:0:note":"かれ","grammar:2051:ex:words:0:pos":"pronoun","grammar:2051:ex:words:1:zh":"(topic marker)","grammar:2051:ex:words:1:pos":"particle","grammar:2051:ex:words:2:zh":"doctor","grammar:2051:ex:words:2:note":"いしゃ","grammar:2051:ex:words:2:pos":"noun","grammar:2051:ex:words:3:zh":"(result of the change)","grammar:2051:ex:words:3:pos":"particle","grammar:2051:ex:words:4:zh":"want to become","grammar:2051:ex:words:4:note":"なりたい；〜たい wish","grammar:2051:ex:words:4:pos":"verb","grammar:2051:ex:words:5:zh":"(quotation)","grammar:2051:ex:words:5:pos":"particle","grammar:2051:ex:words:6:zh":"said","grammar:2051:ex:words:6:note":"いった","grammar:2051:ex:words:6:pos":"verb","grammar:2051:ex:points:0":"〜になりたい: to want to become…","grammar:2051:ex:points:1":"〜と言った: said that… (quotation)","grammar:2051:ex2:trans":"Summer is almost here.","grammar:2051:ex2:structure":"〜になります","grammar:2051:ex2:words:0:zh":"soon, right away","grammar:2051:ex2:words:0:pos":"adverb","grammar:2051:ex2:words:1:zh":"summer","grammar:2051:ex2:words:1:note":"なつ","grammar:2051:ex2:words:1:pos":"noun","grammar:2051:ex2:words:2:zh":"(result of the change)","grammar:2051:ex2:words:2:pos":"particle","grammar:2051:ex2:words:3:zh":"became, reached","grammar:2051:ex2:words:3:note":"the masu-form of なる","grammar:2051:ex2:words:3:pos":"verb","grammar:2051:ex2:points:0":"「夏になります」: noun＋「になる」 shows a change into a state, and this is also how you say a season or a time has arrived.","grammar:2051:ex2:points:1":"「もうすぐ」 = soon, and it often appears with 「なる」 to show a change that is about to happen.","grammar:2051:ex3:trans":"After graduating from university, she became a teacher.","grammar:2051:ex3:structure":"noun＋を＋〔卒業して〕、noun＋に＋なった。「卒業して」 uses the te-form to link the two actions.","grammar:2051:ex3:words:0:zh":"she","grammar:2051:ex3:words:0:note":"かのじょ","grammar:2051:ex3:words:0:pos":"pronoun","grammar:2051:ex3:words:1:zh":"(topic marker)","grammar:2051:ex3:words:1:pos":"particle","grammar:2051:ex3:words:2:zh":"university","grammar:2051:ex3:words:2:note":"だいがく","grammar:2051:ex3:words:2:pos":"noun","grammar:2051:ex3:words:3:zh":"(object marker)","grammar:2051:ex3:words:3:pos":"particle","grammar:2051:ex3:words:4:zh":"graduated (and then)","grammar:2051:ex3:words:4:note":"そつぎょうして；te-form linking","grammar:2051:ex3:words:4:pos":"verb","grammar:2051:ex3:words:5:zh":"teacher","grammar:2051:ex3:words:5:note":"きょうし","grammar:2051:ex3:words:5:pos":"noun","grammar:2051:ex3:words:6:zh":"(result of the change)","grammar:2051:ex3:words:6:pos":"particle","grammar:2051:ex3:words:7:zh":"became","grammar:2051:ex3:words:7:note":"the ta-form of 〜になる","grammar:2051:ex3:words:7:pos":"verb","grammar:2051:ex3:points:0":"〜を卒業する: to graduate from…","grammar:2051:ex3:points:1":"te-form linking: 卒業して〜になった (graduated, then became…)","grammar:2051:ex4:trans":"If you go to Japan, you can come into contact with (different) cultures.","grammar:2051:ex4:structure":"〜と、〜ことができる＋ようになります。「〜ようになる」 shows a change in ability or state: to become able to…","grammar:2051:ex4:words:0:zh":"Japan","grammar:2051:ex4:words:0:note":"にほん","grammar:2051:ex4:words:0:pos":"noun","grammar:2051:ex4:words:1:zh":"(destination)","grammar:2051:ex4:words:1:pos":"particle","grammar:2051:ex4:words:2:zh":"go","grammar:2051:ex4:words:2:note":"いく；dictionary form","grammar:2051:ex4:words:2:pos":"verb","grammar:2051:ex4:words:3:zh":"(as soon as…)","grammar:2051:ex4:words:3:pos":"particle","grammar:2051:ex4:words:4:zh":"culture","grammar:2051:ex4:words:4:note":"ぶんか","grammar:2051:ex4:words:4:pos":"noun","grammar:2051:ex4:words:5:zh":"(object)","grammar:2051:ex4:words:5:pos":"particle","grammar:2051:ex4:words:6:zh":"contact","grammar:2051:ex4:words:6:note":"ふれる；dictionary form","grammar:2051:ex4:words:6:pos":"verb","grammar:2051:ex4:words:7:zh":"be able to","grammar:2051:ex4:words:7:note":"〜ことができる","grammar:2051:ex4:words:7:pos":"Phrase","grammar:2051:ex4:words:8:zh":"to become able to…","grammar:2051:ex4:words:8:note":"〜ようになる: to become able to…","grammar:2051:ex4:words:8:pos":"Phrase","grammar:2051:ex4:points:0":"〜ことができる: to be able to…","grammar:2051:ex4:points:1":"〜ようになる: to become able to… (a change of state)","grammar:2051:ex5:trans":"My older brother turned twenty last year.","grammar:2051:ex5:structure":"〜は…歳になりました","grammar:2051:ex5:words:0:zh":"(my) older brother","grammar:2051:ex5:words:0:note":"あに","grammar:2051:ex5:words:0:pos":"noun","grammar:2051:ex5:words:1:zh":"(topic)","grammar:2051:ex5:words:1:pos":"particle","grammar:2051:ex5:words:2:zh":"last year","grammar:2051:ex5:words:2:note":"きょねん","grammar:2051:ex5:words:2:pos":"noun","grammar:2051:ex5:words:3:zh":"twenty years old","grammar:2051:ex5:words:3:note":"はたち","grammar:2051:ex5:words:3:pos":"noun","grammar:2051:ex5:words:4:zh":"(result of the change)","grammar:2051:ex5:words:4:pos":"particle","grammar:2051:ex5:words:5:zh":"became","grammar:2051:ex5:words:5:note":"past masu-form of なる","grammar:2051:ex5:words:5:pos":"verb","grammar:2051:ex5:points:0":"「二十歳になりました」: to talk about getting older, use 「〜歳になる」; 「に」 marks the result after the change.","grammar:2051:ex5:points:1":"「二十歳」 is read specially as 「はたち」, not 「にじゅっさい」.","grammar:2051:ex5:points:2":"「兄」 is used when you talk about your own older brother to outsiders; to refer to someone else's older brother, use 「お兄さん」.","exam:2051:zh":"My little brother turns six next month, so I'll make a cake on his birthday.","exam:2051:why":"For an age becoming six, you say 「六歳になる」. 「する」 is usually used for actively doing something and can't express age increasing on its own."},"2052":{"example:2052:exzh":"He works as a pilot.","example:2052:exzh2":"Training is necessary to become a pilot.","example:2052:exzh3":"A pilot's job is dangerous, but it's rewarding.","example:2052:exzh4":"I have a dream of being a pilot flying through the sky.","example:2052:exzh5":"She aims to become a pilot."},"2053":{"example:2053:exzh":"Disappointment is part of life.","example:2053:exzh3":"I was betrayed by a friend and felt disappointed.","example:2053:exzh4":"She had expectations that were too high and was disappointed.","example:2053:exzh5":"Don't be disappointed — there will be another chance."},"2054":{"example:2054:exzh":"I like swimming in the pool.","example:2054:exzh2":"Even in winter there is a heated pool.","example:2054:exzh3":"He plans to go to the pool.","example:2054:exzh4":"The pool is kept clean.","example:2054:exzh5":"In summer there are many people at the pool.","grammar:2054:ex:trans":"I like swimming in the pool.","grammar:2054:ex:structure":"プールで泳ぐのが好きです","grammar:2054:ex:explain":"This sentence combines 「で」 for place with 「〜のが好き」 for likes. The 「で」 in 「プールで」 marks the location of the action of swimming — in the pool. In 「泳ぐのが好き」, the verb 「泳ぐ」 is nominalized with 「の」, then marked with 「が」 as the object of liking, followed by 「好き」. This is the standard way to say you like doing something: plain form verb plus 「のが好きです」. Note that the object of liking takes 「が」, not 「を」. The whole sentence makes both the place and the preference clear: I like swimming in the pool.","grammar:2054:ex:words:0:zh":"swimming pool","grammar:2054:ex:words:0:note":"loanword","grammar:2054:ex:words:0:pos":"noun","grammar:2054:ex:words:1:zh":"(place)","grammar:2054:ex:words:1:pos":"particle","grammar:2054:ex:words:2:zh":"to swim","grammar:2054:ex:words:2:note":"およぐ","grammar:2054:ex:words:2:pos":"verb","grammar:2054:ex:words:3:zh":"(nominalizer)","grammar:2054:ex:words:3:pos":"particle","grammar:2054:ex:words:4:zh":"(object)","grammar:2054:ex:words:4:pos":"particle","grammar:2054:ex:words:5:zh":"to like","grammar:2054:ex:words:5:note":"すき","grammar:2054:ex:words:5:pos":"na-adjective","grammar:2054:ex:words:6:zh":"(polite form)","grammar:2054:ex:words:6:pos":"copula","grammar:2054:ex:points:0":"❗プール: swimming pool (pool); ❓プールで = in the pool (で marks place); 泳ぐ = to swim.","grammar:2054:ex:points:1":"プール: swimming pool.","grammar:2054:ex2:trans":"There is even a heated pool in winter.","grammar:2054:ex2:structure":"冬でも温水プールがあります","grammar:2054:ex2:words:0:zh":"winter","grammar:2054:ex2:words:0:note":"ふゆ","grammar:2054:ex2:words:0:pos":"noun","grammar:2054:ex2:words:1:zh":"even","grammar:2054:ex2:words:1:pos":"particle","grammar:2054:ex2:words:2:zh":"heated pool","grammar:2054:ex2:words:2:note":"おんすいプール","grammar:2054:ex2:words:2:pos":"noun","grammar:2054:ex2:words:3:zh":"(nominative)","grammar:2054:ex2:words:3:pos":"particle","grammar:2054:ex2:words:4:zh":"there is / are","grammar:2054:ex2:words:4:pos":"verb","grammar:2054:ex2:points:0":"❗温水プール: heated pool (温水 plus pool); 〜でも = even…","grammar:2054:ex2:points:1":"温水プール: heated pool.","grammar:2054:ex3:trans":"He plans to go to the pool.","grammar:2054:ex3:structure":"プールに行く予定です","grammar:2054:ex3:words:0:zh":"he","grammar:2054:ex3:words:0:note":"かれ","grammar:2054:ex3:words:0:pos":"pronoun","grammar:2054:ex3:words:1:zh":"(topic)","grammar:2054:ex3:words:1:pos":"particle","grammar:2054:ex3:words:2:zh":"swimming pool","grammar:2054:ex3:words:2:note":"loanword","grammar:2054:ex3:words:2:pos":"noun","grammar:2054:ex3:words:3:zh":"(destination)","grammar:2054:ex3:words:3:pos":"particle","grammar:2054:ex3:words:4:zh":"go","grammar:2054:ex3:words:4:note":"いく","grammar:2054:ex3:words:4:pos":"verb","grammar:2054:ex3:words:5:zh":"plans","grammar:2054:ex3:words:5:note":"よてい","grammar:2054:ex3:words:5:pos":"noun","grammar:2054:ex3:words:6:zh":"(polite form)","grammar:2054:ex3:words:6:pos":"copula","grammar:2054:ex3:points:0":"❗プールに行く: to go to the pool; 〜予定 = a plan to…","grammar:2054:ex3:points:1":"プールに行く: to go to the pool.","grammar:2054:ex4:trans":"The pool is kept clean.","grammar:2054:ex4:structure":"プールは清潔に保たれています","grammar:2054:ex4:words:0:zh":"swimming pool","grammar:2054:ex4:words:0:note":"loanword","grammar:2054:ex4:words:0:pos":"noun","grammar:2054:ex4:words:1:zh":"(topic)","grammar:2054:ex4:words:1:pos":"particle","grammar:2054:ex4:words:2:zh":"clean","grammar:2054:ex4:words:2:note":"せいけつ","grammar:2054:ex4:words:2:pos":"na-adjective","grammar:2054:ex4:words:3:zh":"(result)","grammar:2054:ex4:words:3:pos":"particle","grammar:2054:ex4:words:4:zh":"is kept","grammar:2054:ex4:words:4:note":"たもたれています","grammar:2054:ex4:words:4:pos":"verb","grammar:2054:ex4:points:0":"❗清潔に保つ: to keep clean; 保たれる = to be maintained (passive).","grammar:2054:ex4:points:1":"清潔に保つ: to keep clean.","grammar:2054:ex5:trans":"In summer there are lots of people at the pool.","grammar:2054:ex5:structure":"夏はプールに人がたくさんいます","grammar:2054:ex5:words:0:zh":"summer","grammar:2054:ex5:words:0:note":"なつ","grammar:2054:ex5:words:0:pos":"noun","grammar:2054:ex5:words:1:zh":"(topic)","grammar:2054:ex5:words:1:pos":"particle","grammar:2054:ex5:words:2:zh":"swimming pool","grammar:2054:ex5:words:2:note":"loanword","grammar:2054:ex5:words:2:pos":"noun","grammar:2054:ex5:words:3:zh":"(location of existence)","grammar:2054:ex5:words:3:pos":"particle","grammar:2054:ex5:words:4:zh":"person","grammar:2054:ex5:words:4:note":"ひと","grammar:2054:ex5:words:4:pos":"noun","grammar:2054:ex5:words:5:zh":"(nominative)","grammar:2054:ex5:words:5:pos":"particle","grammar:2054:ex5:words:6:zh":"a lot","grammar:2054:ex5:words:6:pos":"adverb","grammar:2054:ex5:words:7:zh":"there is / are","grammar:2054:ex5:words:7:pos":"verb","grammar:2054:ex5:points:0":"❗プールに人がいる: there are people at the pool; たくさん = a lot.","grammar:2054:ex5:points:1":"プールに人: people at the pool."},"2055":{"example:2055:exzh":"I take a shower every morning.","example:2055:exzh2":"Bathing in the sunlight feels good.","example:2055:exzh3":"I take a shower after exercising.","example:2055:exzh4":"She soaked up the sun at the seaside.","example:2055:exzh5":"I got drenched in the rain.","grammar:2055:ex:trans":"I take a shower every morning.","grammar:2055:ex:structure":"time＋nounを＋浴びます. 「シャワーを浴びる」 = take a shower (a set phrase).","grammar:2055:ex:explain":"The core of this sentence is the set phrase 「シャワーを浴びる」. 「浴びる」 literally means to bathe or pour over, and together with 「シャワー」 it forms the fixed expression to take a shower; the thing being poured over is marked with 「を」. Japanese has two ways to talk about bathing: soaking in a tub is 「お風呂に入る」, while standing under a shower is 「シャワーを浴びる」 — different wording. 「毎朝」 is a noun used as a time adverb, every morning. 「浴びます」 is the polite form. The whole sentence describes the habit of showering every morning, so remember that 「浴びる」 goes with 「シャワー」.","grammar:2055:ex:words:0:zh":"every morning","grammar:2055:ex:words:0:note":"まいあさ","grammar:2055:ex:words:0:pos":"noun","grammar:2055:ex:words:1:zh":"shower","grammar:2055:ex:words:1:note":"loanword for shower","grammar:2055:ex:words:1:pos":"noun","grammar:2055:ex:words:2:zh":"(object marker)","grammar:2055:ex:words:2:pos":"particle","grammar:2055:ex:words:3:zh":"pour over / rinse","grammar:2055:ex:words:3:note":"あびます; シャワーを浴びる = take a shower","grammar:2055:ex:words:3:pos":"verb","grammar:2055:ex:points:0":"シャワーを浴びる: take a shower (set phrase)","grammar:2055:ex:points:1":"浴びる: bathe, pour over","grammar:2055:ex2:trans":"Basking in the sunlight feels nice.","grammar:2055:ex2:structure":"〔〜を浴びる＋の〕＋が＋i-adjective. 「日差しを浴びる」 = bask in the sunlight.","grammar:2055:ex2:words:0:zh":"sunlight","grammar:2055:ex2:words:0:note":"ひざし","grammar:2055:ex2:words:0:pos":"noun","grammar:2055:ex2:words:1:zh":"(object marker)","grammar:2055:ex2:words:1:pos":"particle","grammar:2055:ex2:words:2:zh":"bask in / bathe in","grammar:2055:ex2:words:2:note":"あびる","grammar:2055:ex2:words:2:pos":"verb","grammar:2055:ex2:words:3:zh":"(nominalizer)","grammar:2055:ex2:words:3:pos":"particle","grammar:2055:ex2:words:4:zh":"(nominative)","grammar:2055:ex2:words:4:pos":"particle","grammar:2055:ex2:words:5:zh":"comfortable / pleasant","grammar:2055:ex2:words:5:note":"ここちよい","grammar:2055:ex2:words:5:pos":"adjective","grammar:2055:ex2:words:6:zh":"(polite form)","grammar:2055:ex2:words:6:pos":"copula","grammar:2055:ex2:points:0":"verb＋の＋が心地良い: doing … feels pleasant","grammar:2055:ex2:points:1":"日差しを浴びる: soak up the sun / bask in the sunlight","grammar:2055:ex3:trans":"I take a shower after exercising.","grammar:2055:ex3:structure":"noun の 後で＋シャワー を＋浴びます","grammar:2055:ex3:words:0:zh":"exercise","grammar:2055:ex3:words:0:note":"うんどう; exercise, moving your body","grammar:2055:ex3:words:0:pos":"noun","grammar:2055:ex3:words:1:zh":"links","grammar:2055:ex3:words:1:pos":"particle","grammar:2055:ex3:words:2:zh":"later, afterwards","grammar:2055:ex3:words:2:note":"あと; the time after","grammar:2055:ex3:words:2:pos":"noun","grammar:2055:ex3:words:3:zh":"point in time","grammar:2055:ex3:words:3:pos":"particle","grammar:2055:ex3:words:4:zh":"shower","grammar:2055:ex3:words:4:pos":"noun","grammar:2055:ex3:words:5:zh":"object","grammar:2055:ex3:words:5:pos":"particle","grammar:2055:ex3:words:6:zh":"shower; receive","grammar:2055:ex3:words:6:note":"あび; masu-form stem","grammar:2055:ex3:words:6:pos":"verb","grammar:2055:ex3:words:7:zh":"polite","grammar:2055:ex3:words:7:pos":"auxiliary verb","grammar:2055:ex3:points:0":"「シャワーを浴びます」 is a set phrase meaning to take a shower.","grammar:2055:ex3:points:1":"「運動の後で」 shows that the action happens after exercising.","grammar:2055:ex3:points:2":"「浴びます」 is the polite form of 「浴びる」, common at the N4 level.","grammar:2055:ex4:trans":"She soaked up the sun at the seaside.","grammar:2055:ex4:structure":"〜は＋placeで＋日差しを浴びました","grammar:2055:ex4:explain":"「海辺で」 shows the action takes place at the seaside. 「日差しを浴びる」 means letting sunlight fall on your body, so it can be translated as soak up the sun. 「浴びる」 is an ichidan (ru-) verb: drop 「る」 and add 「ました」 to get the polite past form 「浴びました」.","grammar:2055:ex4:words:0:zh":"she","grammar:2055:ex4:words:0:note":"かのじょ","grammar:2055:ex4:words:0:pos":"pronoun","grammar:2055:ex4:words:1:zh":"(topic)","grammar:2055:ex4:words:1:pos":"particle","grammar:2055:ex4:words:2:zh":"seaside","grammar:2055:ex4:words:2:note":"うみべ","grammar:2055:ex4:words:2:pos":"noun","grammar:2055:ex4:words:3:zh":"(place of the action)","grammar:2055:ex4:words:3:pos":"particle","grammar:2055:ex4:words:4:zh":"sunlight","grammar:2055:ex4:words:4:note":"ひざし","grammar:2055:ex4:words:4:pos":"noun","grammar:2055:ex4:words:5:zh":"(object)","grammar:2055:ex4:words:5:pos":"particle","grammar:2055:ex4:words:6:zh":"bathe in; be exposed to","grammar:2055:ex4:words:6:note":"あび","grammar:2055:ex4:words:6:pos":"verb","grammar:2055:ex4:words:7:zh":"(polite tone)","grammar:2055:ex4:words:7:pos":"auxiliary verb","grammar:2055:ex4:words:8:zh":"(past)","grammar:2055:ex4:words:8:pos":"auxiliary verb","grammar:2055:ex4:points:0":"Besides taking a shower, 「浴びる」 can also mean having sunlight fall on your body.","grammar:2055:ex4:points:1":"「海辺で」 marks where the action happens, and 「日差しを」 marks what the body is exposed to.","grammar:2055:ex5:trans":"I got soaked through in the rain.","grammar:2055:ex5:structure":"〔雨の中〕＋で＋〔濡れて〕＋浴びてしまった. 「〜てしまった」 expresses doing something completely / with regret.","grammar:2055:ex5:words:0:zh":"rain","grammar:2055:ex5:words:0:note":"あめ","grammar:2055:ex5:words:0:pos":"noun","grammar:2055:ex5:words:1:zh":"'s","grammar:2055:ex5:words:1:pos":"particle","grammar:2055:ex5:words:2:zh":"during","grammar:2055:ex5:words:2:note":"なか","grammar:2055:ex5:words:2:pos":"noun","grammar:2055:ex5:words:3:zh":"(place)","grammar:2055:ex5:words:3:pos":"particle","grammar:2055:ex5:words:4:zh":"get wet (and)","grammar:2055:ex5:words:4:note":"ぬれて; te-form","grammar:2055:ex5:words:4:pos":"verb","grammar:2055:ex5:words:5:zh":"get drenched (all over)","grammar:2055:ex5:words:5:note":"〜てしまう expresses completion / regret","grammar:2055:ex5:words:5:pos":"verb","grammar:2055:ex5:points:0":"〜の中で: inside … / among …","grammar:2055:ex5:points:1":"〜てしまった: (did completely, with a hint of regret)"},"2056":{"example:2056:exzh":"That tower is famous.","example:2056:exzh2":"You can see the scenery from the top of the tower.","example:2056:exzh3":"This tower has a long history.","example:2056:exzh4":"You need money to climb the tower.","example:2056:exzh5":"I'm looking forward to visiting that tower."},"2057":{"example:2057:exzh":"He claims he is innocent.","example:2057:exzh2":"A not-guilty verdict was handed down.","example:2057:exzh3":"If found not guilty, no compensation is paid.","example:2057:exzh4":"An innocent person will not be sent to prison.","example:2057:exzh5":"Proving innocence is difficult."},"2058":{"example:2058:exzh":"There was a shooting incident in the street last night.","example:2058:exzh2":"There are people who were injured in the shooting.","example:2058:exzh3":"The truth of the shooting incident is under investigation.","example:2058:exzh4":"He was arrested as the shooter.","example:2058:exzh5":"I'm worried about the safety of the area where the shooting happened."},"2059":{"example:2059:exzh":"There is a book on the desk.","example:2059:exzh2":"He bought a new desk.","example:2059:exzh3":"My desk is messy.","example:2059:exzh4":"This table is expensive.","example:2059:exzh5":"I study at my desk every day.","grammar:2059:ex:trans":"There is a book on the desk.","grammar:2059:ex:structure":"机の上に本があります","grammar:2059:ex:explain":"The core of this sentence is 「〜に〜がある」, which expresses existence. In 「本があります」, 「ある」 states that an inanimate thing exists — there is a book; the thing that exists, 「本」, is marked with 「が」, and the place, 「机の上」, is marked with 「に」. 「机の上に」 uses 「の」 to link the top of the desk. The whole sentence, there is a book on the desk, is the basic existence pattern describing where something is: place plus 「に」 plus subject plus 「が」 plus 「あります」. Remember that living things such as people or animals take 「いる」; only inanimate things take 「ある」.","grammar:2059:ex:words:0:zh":"desk","grammar:2059:ex:words:0:note":"つくえ","grammar:2059:ex:words:0:pos":"noun","grammar:2059:ex:words:1:zh":"'s","grammar:2059:ex:words:1:pos":"particle","grammar:2059:ex:words:2:zh":"on top of","grammar:2059:ex:words:2:note":"うえ","grammar:2059:ex:words:2:pos":"noun","grammar:2059:ex:words:3:zh":"(location of existence)","grammar:2059:ex:words:3:pos":"particle","grammar:2059:ex:words:4:zh":"book","grammar:2059:ex:words:4:note":"ほん","grammar:2059:ex:words:4:pos":"noun","grammar:2059:ex:words:5:zh":"(nominative)","grammar:2059:ex:words:5:pos":"particle","grammar:2059:ex:words:6:zh":"there is / are","grammar:2059:ex:words:6:pos":"verb","grammar:2059:ex:points:0":"❗机（つくえ）: desk, writing desk (for studying or office work; a dining table is 「テーブル」).","grammar:2059:ex:points:1":"机: desk.","grammar:2059:ex2:trans":"He bought a new desk.","grammar:2059:ex2:structure":"新しい机を買いました","grammar:2059:ex2:words:0:zh":"he","grammar:2059:ex2:words:0:note":"かれ","grammar:2059:ex2:words:0:pos":"pronoun","grammar:2059:ex2:words:1:zh":"(topic)","grammar:2059:ex2:words:1:pos":"particle","grammar:2059:ex2:words:2:zh":"new","grammar:2059:ex2:words:2:note":"あたらしい","grammar:2059:ex2:words:2:pos":"adjective","grammar:2059:ex2:words:3:zh":"desk","grammar:2059:ex2:words:3:note":"つくえ","grammar:2059:ex2:words:3:pos":"noun","grammar:2059:ex2:words:4:zh":"(object marker)","grammar:2059:ex2:words:4:pos":"particle","grammar:2059:ex2:words:5:zh":"bought","grammar:2059:ex2:words:5:note":"かいました","grammar:2059:ex2:words:5:pos":"verb","grammar:2059:ex2:points:0":"❗新しい机: a new desk.","grammar:2059:ex2:points:1":"新しい机: new desk.","grammar:2059:ex3:trans":"My desk is messy.","grammar:2059:ex3:structure":"私の机は散らかっています","grammar:2059:ex3:words:0:zh":"I","grammar:2059:ex3:words:0:note":"わたし","grammar:2059:ex3:words:0:pos":"pronoun","grammar:2059:ex3:words:1:zh":"'s","grammar:2059:ex3:words:1:pos":"particle","grammar:2059:ex3:words:2:zh":"desk","grammar:2059:ex3:words:2:note":"つくえ","grammar:2059:ex3:words:2:pos":"noun","grammar:2059:ex3:words:3:zh":"(topic)","grammar:2059:ex3:words:3:pos":"particle","grammar:2059:ex3:words:4:zh":"messy","grammar:2059:ex3:words:4:note":"ちらかっています","grammar:2059:ex3:words:4:pos":"verb","grammar:2059:ex3:points:0":"❗散らかる: to be cluttered, to be messy (intransitive verb); 机が散らかる = the desk is a mess.","grammar:2059:ex3:points:1":"「散らかる」: be messy.","grammar:2059:ex4:trans":"This table is expensive.","grammar:2059:ex4:structure":"この机はとても高いです","grammar:2059:ex4:words:0:zh":"this","grammar:2059:ex4:words:0:pos":"pre-noun adjectival","grammar:2059:ex4:words:1:zh":"desk","grammar:2059:ex4:words:1:note":"つくえ","grammar:2059:ex4:words:1:pos":"noun","grammar:2059:ex4:words:2:zh":"(topic)","grammar:2059:ex4:words:2:pos":"particle","grammar:2059:ex4:words:3:zh":"extremely","grammar:2059:ex4:words:3:pos":"adverb","grammar:2059:ex4:words:4:zh":"expensive","grammar:2059:ex4:words:4:note":"たかい","grammar:2059:ex4:words:4:pos":"adjective","grammar:2059:ex4:words:5:zh":"(polite form)","grammar:2059:ex4:words:5:pos":"copula","grammar:2059:ex4:points:0":"❗高い: expensive (price)／tall, high (height); here it means expensive.","grammar:2059:ex4:points:1":"高い: expensive.","grammar:2059:ex5:trans":"I study at my desk every day.","grammar:2059:ex5:structure":"毎日机で勉強します","grammar:2059:ex5:words:0:zh":"every day","grammar:2059:ex5:words:0:note":"まいにち","grammar:2059:ex5:words:0:pos":"adverb","grammar:2059:ex5:words:1:zh":"desk","grammar:2059:ex5:words:1:note":"つくえ","grammar:2059:ex5:words:1:pos":"noun","grammar:2059:ex5:words:2:zh":"(place)","grammar:2059:ex5:words:2:pos":"particle","grammar:2059:ex5:words:3:zh":"to study","grammar:2059:ex5:words:3:note":"べんきょうします","grammar:2059:ex5:words:3:pos":"verb","grammar:2059:ex5:points:0":"❗❓机で = at the desk (で marks where the action takes place); 勉強する = to study.","grammar:2059:ex5:points:1":"机で勉強: studying at the desk.","exam:2059:zh":"In the classroom, I put the notebook on the desk, sit on a chair, and write.","exam:2059:why":"A desk provides the surface for setting down a notebook and writing. A chair is for sitting, and the sentence already says you sit on a chair."},"2060":{"example:2060:exzh":"His commotion was so big that the people around him were startled.","example:2060:exzh2":"Let's avoid causing a commotion.","example:2060:exzh3":"After the festival commotion ended, the streets became quiet.","example:2060:exzh4":"People who cause a commotion are disliked.","example:2060:exzh5":"That commotion soon died down."},"2061":{"example:2061:exzh":"Don't pick your nose in front of others.","example:2061:exzh2":"That man used words like shit.","example:2061:exzh3":"This is exactly the pot calling the kettle black.","example:2061:exzh4":"I felt that what he said was crap.","example:2061:exzh5":"He's dead serious, so jokes never get through to him at all."},"2062":{"example:2062:exzh":"Black culture is extremely diverse.","example:2062:exzh2":"He is proud of being Black.","example:2062:exzh3":"It's important to learn about Black history.","example:2062:exzh4":"Black artists are drawing attention.","example:2062:exzh5":"We are taking part in activities to protect the rights of Black people."},"2063":{"example:2063:exzh":"This deal is very important.","example:2063:exzh2":"They discussed the transaction.","example:2063:exzh3":"Our goal is to increase the number of business partners.","example:2063:exzh4":"The moment the deal went through, my excitement rose.","example:2063:exzh5":"We need to confirm the terms of the transaction."},"2064":{"example:2064:exzh":"I used the camera's flash.","example:2064:exzh2":"At that instant, the flash went off.","example:2064:exzh3":"The light from the flash was blinding.","example:2064:exzh4":"Use the flash to take a photo.","example:2064:exzh5":"Once the flash faded, the screen turned bright."},"2065":{"example:2065:exzh":"I'm looking forward to going back to my hometown.","example:2065:exzh2":"He regrets leaving his hometown.","example:2065:exzh3":"The scenery of the hometown is beautiful.","example:2065:exzh4":"I want to see friends from my hometown.","example:2065:exzh5":"The scent of the hometown makes me nostalgic."},"2066":{"example:2066:exzh":"He apologized for having an affair.","example:2066:exzh2":"Having an affair is an act of betraying trust.","example:2066:exzh3":"Once an affair is discovered, the relationship often ends.","example:2066:exzh4":"She began to suspect an affair.","example:2066:exzh5":"If someone is having an affair, it's better to think about breaking up."},"2067":{"example:2067:exzh":"The police found the weapon.","example:2067:exzh2":"In this case, the weapon needs to be identified.","example:2067:exzh3":"Using a weapon is not permitted.","example:2067:exzh4":"He was calm as he gripped the weapon.","example:2067:exzh5":"If the weapon isn't found, the investigation won't move forward."},"2068":{"example:2068:exzh":"They have a hobby in common.","example:2068:exzh2":"Let's work hard toward a common goal.","example:2068:exzh3":"Finding things in common is fun.","example:2068:exzh4":"I have many friends in common with him.","example:2068:exzh5":"Some people have shared access rights."},"2069":{"example:2069:exzh":"Young people are the ones who will carry the future.","example:2069:exzh2":"We should value young people's opinions.","example:2069:exzh3":"This problem also affects young people.","example:2069:exzh4":"Young people are interested in new technology.","example:2069:exzh5":"I joined a gathering of young people."},"2072":{"example:2072:exzh":"Saying something like that is uncalled for.","example:2072:exzh2":"I felt his advice was unnecessary.","example:2072:exzh3":"Please don't worry unnecessarily.","example:2072:exzh4":"That explanation is unnecessary information.","example:2072:exzh5":"Please don't say unnecessary things."},"2073":{"example:2073:exzh":"I usually start work at 9.","example:2073:exzh2":"Under normal circumstances there's no problem.","example:2073:exzh3":"Usually, he is never late.","example:2073:exzh4":"Please follow the normal rules.","example:2073:exzh5":"Usually she does the cooking."},"2074":{"example:2074:exzh":"I cancelled the contract.","example:2074:exzh2":"We need to lift the restrictions.","example:2074:exzh3":"The rules cannot be lifted.","example:2074:exzh4":"The cancellation procedure is simple.","example:2074:exzh5":"This account has been deactivated."},"2075":{"example:2075:exzh":"What happened?","example:2075:exzh2":"He doesn't worry about anything.","example:2075:exzh3":"The beginning is important in anything.","example:2075:exzh4":"What is going on?","example:2075:exzh5":"I'm interested in anything and everything."},"2076":{"example:2076:exzh":"Thailand is a beautiful country.","example:2076:exzh2":"I love Thai food.","example:2076:exzh3":"He lives in Thailand.","example:2076:exzh4":"Thai culture is fascinating.","example:2076:exzh5":"I want to go to Thailand.","grammar:2076:ex:trans":"Thailand is a beautiful country.","grammar:2076:ex:structure":"タイは美しい国です","grammar:2076:ex:explain":"This sentence uses an i-adjective in its attributive form plus a noun predicate. In 「美しい国」, the i-adjective 「美しい」 directly modifies the noun 「国」, giving a beautiful country; an i-adjective attaches to a noun with no change, simply placed before it. 「タイは」 uses 「は」 to present the topic, and the sentence ends with the polite 「です」. The whole sentence, Thailand is a beautiful country, follows the pattern A は (adjective + noun) です. Note that 「美しい」 here is the attributive use modifying a noun, which sits in a different position from its use as the sentence-final predicate in 「〜は美しいです」.","grammar:2076:ex:words:0:zh":"Thailand (place name)","grammar:2076:ex:words:0:pos":"noun","grammar:2076:ex:words:1:zh":"(topic)","grammar:2076:ex:words:1:pos":"particle","grammar:2076:ex:words:2:zh":"beautiful","grammar:2076:ex:words:2:note":"うつくしい","grammar:2076:ex:words:2:pos":"adjective","grammar:2076:ex:words:3:zh":"country","grammar:2076:ex:words:3:note":"くに","grammar:2076:ex:words:3:pos":"noun","grammar:2076:ex:words:4:zh":"is","grammar:2076:ex:words:4:pos":"copula","grammar:2076:ex:points:0":"❗タイ: Thailand (place name).","grammar:2076:ex:points:1":"タイ: Thailand.","grammar:2076:ex2:trans":"I love Thai food.","grammar:2076:ex2:structure":"タイ料理が大好きです","grammar:2076:ex2:words:0:zh":"Thai food","grammar:2076:ex2:words:0:note":"タイりょうり","grammar:2076:ex2:words:0:pos":"noun","grammar:2076:ex2:words:1:zh":"(object)","grammar:2076:ex2:words:1:pos":"particle","grammar:2076:ex2:words:2:zh":"love","grammar:2076:ex2:words:2:note":"だいすき","grammar:2076:ex2:words:2:pos":"na-adjective","grammar:2076:ex2:words:3:zh":"(polite form)","grammar:2076:ex2:words:3:pos":"copula","grammar:2076:ex2:points:0":"❗タイ料理: Thai cuisine (タイ + 料理).","grammar:2076:ex2:points:1":"タイ料理: Thai food.","grammar:2076:ex3:trans":"He lives in Thailand.","grammar:2076:ex3:structure":"タイに住んでいます","grammar:2076:ex3:words:0:zh":"he","grammar:2076:ex3:words:0:note":"かれ","grammar:2076:ex3:words:0:pos":"pronoun","grammar:2076:ex3:words:1:zh":"(topic)","grammar:2076:ex3:words:1:pos":"particle","grammar:2076:ex3:words:2:zh":"Thailand","grammar:2076:ex3:words:2:pos":"noun","grammar:2076:ex3:words:3:zh":"(location of existence)","grammar:2076:ex3:words:3:pos":"particle","grammar:2076:ex3:words:4:zh":"live (there)","grammar:2076:ex3:words:4:note":"すんでいます","grammar:2076:ex3:words:4:pos":"verb","grammar:2076:ex3:points:0":"❗タイに住む: to live in Thailand.","grammar:2076:ex3:points:1":"タイに住む: live in Thailand.","grammar:2076:ex4:trans":"Thai culture is fascinating.","grammar:2076:ex4:structure":"タイの文化は興味深いです","grammar:2076:ex4:words:0:zh":"Thailand","grammar:2076:ex4:words:0:pos":"noun","grammar:2076:ex4:words:1:zh":"'s","grammar:2076:ex4:words:1:pos":"particle","grammar:2076:ex4:words:2:zh":"culture","grammar:2076:ex4:words:2:note":"ぶんか","grammar:2076:ex4:words:2:pos":"noun","grammar:2076:ex4:words:3:zh":"(topic)","grammar:2076:ex4:words:3:pos":"particle","grammar:2076:ex4:words:4:zh":"fascinating; intriguing","grammar:2076:ex4:words:4:note":"きょうみぶかい","grammar:2076:ex4:words:4:pos":"adjective","grammar:2076:ex4:words:5:zh":"(polite form)","grammar:2076:ex4:words:5:pos":"copula","grammar:2076:ex4:points:0":"❗興味深い: deeply interesting; thought-provoking (興味 + 深い).","grammar:2076:ex4:points:1":"興味深い: interesting; intriguing.","grammar:2076:ex5:trans":"I want to go to Thailand.","grammar:2076:ex5:structure":"タイに行きたいです","grammar:2076:ex5:words:0:zh":"Thailand","grammar:2076:ex5:words:0:pos":"noun","grammar:2076:ex5:words:1:zh":"(destination)","grammar:2076:ex5:words:1:pos":"particle","grammar:2076:ex5:words:2:zh":"want to go","grammar:2076:ex5:words:2:note":"いきたい","grammar:2076:ex5:words:2:pos":"verb","grammar:2076:ex5:words:3:zh":"(polite form)","grammar:2076:ex5:words:3:pos":"copula","grammar:2076:ex5:points:0":"❗タイに行く: to go to Thailand; 〜たい = to want to …","grammar:2076:ex5:points:1":"タイに行く: go to Thailand."},"2079":{"example:2079:exzh":"Nelson is a famous writer.","example:2079:exzh2":"I've been friends with Nelson for a long time.","example:2079:exzh3":"I love Nelson's work.","example:2079:exzh4":"Nelson likes traveling.","example:2079:exzh5":"We celebrate Nelson's birthday."},"2080":{"example:2080:exzh":"He is worried about work.","example:2080:exzh2":"Friends you can talk to when you're worried are precious.","example:2080:exzh3":"What's troubling you?","example:2080:exzh4":"She always worries alone.","example:2080:exzh5":"I consulted an expert to solve what was troubling me."},"2082":{"example:2082:exzh":"Teasing friends is not good.","example:2082:exzh2":"He likes teasing his companions.","example:2082:exzh3":"Being teased put me in a bad mood.","example:2082:exzh4":"Children often tease each other.","example:2082:exzh5":"She finds teasing him fun."},"2083":{"example:2083:exzh":"There are many animals on the farm.","example:2083:exzh2":"I went to a farm on my day off.","example:2083:exzh3":"He likes working on a farm.","example:2083:exzh4":"I bought fresh vegetables from the farm.","example:2083:exzh5":"My dream is to have my own farm."},"2084":{"example:2084:exzh":"I picked up trash lying on the ground.","example:2084:exzh2":"He picked up a wallet on the street.","example:2084:exzh3":"The children are picking up seashells on the beach.","example:2084:exzh4":"I picked up an umbrella on a rainy day.","example:2084:exzh5":"He picked up a dog on the street.","grammar:2084:ex:trans":"I picked up the trash lying on the ground.","grammar:2084:ex:structure":"〜を拾いました","grammar:2084:ex:explain":"The core of this sentence is a 「〜ている」 verb modifying a noun. In 「落ちているゴミ」, 「いる」 is added to the te-form of 「落ちる」 to show the state of having fallen, and the whole phrase sits before the noun 「ゴミ」 to modify it, meaning trash lying on the ground. The 「に」 in 「地面に」 marks the place where it exists. 「拾いました」 is the past polite form of the transitive verb 「拾う」 (to pick up), and the object 「ゴミ」 takes 「を」. This sentence, meaning I picked up the trash on the ground, demonstrates the 「〜ている＋noun」 pattern, where a continuing state modifies a noun — a pattern that is very common in descriptive scenes.","grammar:2084:ex:words:0:zh":"ground","grammar:2084:ex:words:0:note":"じめん","grammar:2084:ex:words:0:pos":"noun","grammar:2084:ex:words:1:zh":"(location of existence)","grammar:2084:ex:words:1:pos":"particle","grammar:2084:ex:words:2:zh":"fallen; lying there","grammar:2084:ex:words:2:note":"おちている","grammar:2084:ex:words:2:pos":"verb","grammar:2084:ex:words:3:zh":"trash","grammar:2084:ex:words:3:pos":"noun","grammar:2084:ex:words:4:zh":"(object marker)","grammar:2084:ex:words:4:pos":"particle","grammar:2084:ex:words:5:zh":"picked up","grammar:2084:ex:words:5:note":"ひろいました","grammar:2084:ex:words:5:pos":"verb","grammar:2084:ex:points:0":"❗拾う（ひろう）: to pick up, to pick up (transitive verb); vs 捨てる (to throw away); ゴミを拾う = to pick up trash.","grammar:2084:ex:points:1":"ゴミを拾う: to pick up trash.","grammar:2084:ex2:trans":"He picked up a wallet on the road.","grammar:2084:ex2:structure":"〜で〜を拾った","grammar:2084:ex2:words:0:zh":"he","grammar:2084:ex2:words:0:note":"かれ","grammar:2084:ex2:words:0:pos":"pronoun","grammar:2084:ex2:words:1:zh":"(topic)","grammar:2084:ex2:words:1:pos":"particle","grammar:2084:ex2:words:2:zh":"road","grammar:2084:ex2:words:2:note":"みち","grammar:2084:ex2:words:2:pos":"noun","grammar:2084:ex2:words:3:zh":"(place)","grammar:2084:ex2:words:3:pos":"particle","grammar:2084:ex2:words:4:zh":"wallet","grammar:2084:ex2:words:4:note":"さいふ","grammar:2084:ex2:words:4:pos":"noun","grammar:2084:ex2:words:5:zh":"(object marker)","grammar:2084:ex2:words:5:pos":"particle","grammar:2084:ex2:words:6:zh":"picked up","grammar:2084:ex2:words:6:note":"ひろった","grammar:2084:ex2:words:6:pos":"verb","grammar:2084:ex2:points:0":"❗財布を拾う: to pick up a wallet; ❓道で = on the road (で for place).","grammar:2084:ex2:points:1":"財布を拾う: to pick up a wallet.","grammar:2084:ex3:trans":"The children are picking up seashells on the beach.","grammar:2084:ex3:structure":"〜で〜を拾っています","grammar:2084:ex3:words:0:zh":"children","grammar:2084:ex3:words:0:note":"こどもたち","grammar:2084:ex3:words:0:pos":"noun","grammar:2084:ex3:words:1:zh":"(topic)","grammar:2084:ex3:words:1:pos":"particle","grammar:2084:ex3:words:2:zh":"beach","grammar:2084:ex3:words:2:note":"loanword","grammar:2084:ex3:words:2:pos":"noun","grammar:2084:ex3:words:3:zh":"(place)","grammar:2084:ex3:words:3:pos":"particle","grammar:2084:ex3:words:4:zh":"seashell","grammar:2084:ex3:words:4:note":"かいがら","grammar:2084:ex3:words:4:pos":"noun","grammar:2084:ex3:words:5:zh":"(object marker)","grammar:2084:ex3:words:5:pos":"particle","grammar:2084:ex3:words:6:zh":"are picking up","grammar:2084:ex3:words:6:note":"ひろっています","grammar:2084:ex3:words:6:pos":"verb","grammar:2084:ex3:points:0":"❗貝殻を拾う: to pick up seashells; ビーチ = beach.","grammar:2084:ex3:points:1":"貝殻を拾う: to pick up seashells.","grammar:2084:ex4:trans":"I picked up an umbrella on a rainy day.","grammar:2084:ex4:structure":"〜に〜を拾いました","grammar:2084:ex4:words:0:zh":"rain","grammar:2084:ex4:words:0:note":"あめ","grammar:2084:ex4:words:0:pos":"noun","grammar:2084:ex4:words:1:zh":"'s","grammar:2084:ex4:words:1:pos":"particle","grammar:2084:ex4:words:2:zh":"day","grammar:2084:ex4:words:2:note":"ひ","grammar:2084:ex4:words:2:pos":"noun","grammar:2084:ex4:words:3:zh":"(point in time)","grammar:2084:ex4:words:3:pos":"particle","grammar:2084:ex4:words:4:zh":"umbrella","grammar:2084:ex4:words:4:note":"かさ","grammar:2084:ex4:words:4:pos":"noun","grammar:2084:ex4:words:5:zh":"(object marker)","grammar:2084:ex4:words:5:pos":"particle","grammar:2084:ex4:words:6:zh":"picked up","grammar:2084:ex4:words:6:note":"ひろいました","grammar:2084:ex4:words:6:pos":"verb","grammar:2084:ex4:points:0":"❗雨の日に: on a rainy day; 傘を拾う = to pick up an umbrella.","grammar:2084:ex4:points:1":"傘を拾う: to pick up an umbrella.","grammar:2084:ex5:trans":"He picked up a dog on the road.","grammar:2084:ex5:structure":"〜で〜を拾いました","grammar:2084:ex5:words:0:zh":"he","grammar:2084:ex5:words:0:note":"かれ","grammar:2084:ex5:words:0:pos":"pronoun","grammar:2084:ex5:words:1:zh":"(topic)","grammar:2084:ex5:words:1:pos":"particle","grammar:2084:ex5:words:2:zh":"on the road","grammar:2084:ex5:words:2:note":"ろじょう","grammar:2084:ex5:words:2:pos":"noun","grammar:2084:ex5:words:3:zh":"(place)","grammar:2084:ex5:words:3:pos":"particle","grammar:2084:ex5:words:4:zh":"dog","grammar:2084:ex5:words:4:note":"いぬ","grammar:2084:ex5:words:4:pos":"noun","grammar:2084:ex5:words:5:zh":"(object marker)","grammar:2084:ex5:words:5:pos":"particle","grammar:2084:ex5:words:6:zh":"picked up","grammar:2084:ex5:words:6:note":"ひろいました","grammar:2084:ex5:words:6:pos":"verb","grammar:2084:ex5:points:0":"❗犬を拾う: to pick up a dog (「拾う」 is the usual word for taking in a stray dog); 路上 = on the road.","grammar:2084:ex5:points:1":"犬を拾う: to pick up a dog."},"2085":{"example:2085:exzh":"In this match, winning matters.","example:2085:exzh2":"He won the game.","example:2085:exzh3":"The team is aiming for a win.","example:2085:exzh4":"I'm happy we were able to get the win.","example:2085:exzh5":"We'll give it our all to win."},"2086":{"example:2086:exzh":"Honey, what do you want to eat today?","example:2086:exzh2":"She is my honey.","example:2086:exzh3":"Honey, let's go see a movie.","example:2086:exzh4":"That honey is very kind.","example:2086:exzh5":"Honey, can you give me a hand?"},"2087":{"example:2087:exzh":"There are many elderly people in the park.","example:2087:exzh2":"Listening to elderly people talk is important.","example:2087:exzh3":"That elderly person is very kind.","example:2087:exzh4":"I volunteer at a nursing home.","example:2087:exzh5":"He works in a job that helps elderly people."},"2088":{"example:2088:exzh":"Next week is voting day.","example:2088:exzh2":"I'm getting ready to go vote.","example:2088:exzh3":"Voting is a citizen's right.","example:2088:exzh4":"Various opinions are reflected through voting.","example:2088:exzh5":"She votes actively."},"2089":{"example:2089:exzh":"He is the leader of the group.","example:2089:exzh2":"It's important to act as a group.","example:2089:exzh3":"Lately, group behavior has been increasing.","example:2089:exzh4":"It's necessary to respect the will of the group.","example:2089:exzh5":"A group decision is being called for."},"2090":{"example:2090:exzh":"He was promoted to lieutenant.","example:2090:exzh2":"The work of a lieutenant is tough.","example:2090:exzh3":"The lieutenant is trusted by his subordinates.","example:2090:exzh4":"She completed the lieutenant's mission.","example:2090:exzh5":"A lieutenant plays an important role in the military."},"2091":{"example:2091:exzh":"Sharing information is important.","example:2091:exzh2":"We share experiences.","example:2091:exzh3":"This app makes sharing files easy.","example:2091:exzh4":"We work in a shared space.","example:2091:exzh5":"Knowledge sharing is necessary."},"2092":{"example:2092:exzh":"Dad's arms are very thick.","example:2092:exzh2":"This belt is too wide.","example:2092:exzh3":"She uses a thick pen.","example:2092:exzh4":"I have a thick pen.","example:2092:exzh5":"That fish has a very thick body.","grammar:2092:ex:trans":"My dad's arm is very thick.","grammar:2092:ex:structure":"〜はとても太いです","grammar:2092:ex:explain":"「太い（ふとい）」 is an i-adjective meaning thick, used for rod-shaped or line-shaped things such as 「太い腕」, 「太い木」, and 「太いペン」; it can also describe a low voice, as in 「太い声」. Its opposite is 「細い（ほそい）」. Note that for a person getting fat you do not use 太い but the verb 「太る」, as in 「彼は太った」. For the thickness of flat things like boards and books, use 「厚い」.","grammar:2092:ex:words:0:zh":"father","grammar:2092:ex:words:0:note":"ちち","grammar:2092:ex:words:0:pos":"noun","grammar:2092:ex:words:1:zh":"'s","grammar:2092:ex:words:1:pos":"particle","grammar:2092:ex:words:2:zh":"arm","grammar:2092:ex:words:2:note":"うで","grammar:2092:ex:words:2:pos":"noun","grammar:2092:ex:words:3:zh":"(topic)","grammar:2092:ex:words:3:pos":"particle","grammar:2092:ex:words:4:zh":"well","grammar:2092:ex:words:4:pos":"adverb","grammar:2092:ex:words:5:zh":"thick","grammar:2092:ex:words:5:note":"ふとい","grammar:2092:ex:words:5:pos":"adjective","grammar:2092:ex:words:6:zh":"(polite form)","grammar:2092:ex:words:6:pos":"copula","grammar:2092:ex:points:0":"「腕は太い」: 太い is an i-adjective describing something thick, such as an arm, a leg, a tree trunk, or a line.","grammar:2092:ex:points:1":"「〜は〜です」: an adjective as the predicate, with です added to make it polite.","grammar:2092:ex2:trans":"This belt is too wide.","grammar:2092:ex2:structure":"〜は〜すぎます","grammar:2092:ex2:words:0:zh":"this","grammar:2092:ex2:words:0:pos":"pre-noun adjectival","grammar:2092:ex2:words:1:zh":"belt","grammar:2092:ex2:words:1:pos":"noun","grammar:2092:ex2:words:2:zh":"(topic)","grammar:2092:ex2:words:2:pos":"particle","grammar:2092:ex2:words:3:zh":"too thick, too wide","grammar:2092:ex2:words:3:note":"ふとすぎます; 太い minus い + すぎる","grammar:2092:ex2:words:3:pos":"verb","grammar:2092:ex2:points:0":"「太すぎます」: 太い drops the い and takes 「すぎる」, meaning too thick or too wide — beyond the appropriate degree.","grammar:2092:ex2:points:1":"In Japanese, the width of a belt is also described with 太い／細い.","grammar:2092:ex3:trans":"She uses a thick pen.","grammar:2092:ex3:structure":"is using a thick pen","grammar:2092:ex3:words:0:zh":"she","grammar:2092:ex3:words:0:note":"かのじょ","grammar:2092:ex3:words:0:pos":"pronoun","grammar:2092:ex3:words:1:zh":"(topic)","grammar:2092:ex3:words:1:pos":"particle","grammar:2092:ex3:words:2:zh":"thick","grammar:2092:ex3:words:2:note":"ふとい","grammar:2092:ex3:words:2:pos":"adjective","grammar:2092:ex3:words:3:zh":"pen","grammar:2092:ex3:words:3:note":"loanword","grammar:2092:ex3:words:3:pos":"noun","grammar:2092:ex3:words:4:zh":"(object marker)","grammar:2092:ex3:words:4:pos":"particle","grammar:2092:ex3:words:5:zh":"are using","grammar:2092:ex3:words:5:note":"つかっています","grammar:2092:ex3:words:5:pos":"verb","grammar:2092:ex3:points:0":"❗太いペン: a thick pen (太い as a pre-noun adjectival).","grammar:2092:ex3:points:1":"太いペン: a thick pen.","grammar:2092:ex4:trans":"I have a thick pen.","grammar:2092:ex4:structure":"太い〜を持っています","grammar:2092:ex4:explain":"「太いペン」 usually means a pen with a thick body; if you want to say clearly that the lines it draws are thick, you can say 「太い線が書けるペン」. In the given translation, 「ペンを持っています」 means having such a pen. The te-form of 「持つ」 is 「持って」, and adding 「いる」 describes the state of holding or owning something.","grammar:2092:ex4:words:0:zh":"thick","grammar:2092:ex4:words:0:note":"ふとい","grammar:2092:ex4:words:0:pos":"i-adjective","grammar:2092:ex4:words:1:zh":"pen","grammar:2092:ex4:words:1:pos":"noun","grammar:2092:ex4:words:2:zh":"(object)","grammar:2092:ex4:words:2:pos":"particle","grammar:2092:ex4:words:3:zh":"to have","grammar:2092:ex4:words:3:note":"もっ","grammar:2092:ex4:words:3:pos":"verb","grammar:2092:ex4:words:4:zh":"(links a state expression)","grammar:2092:ex4:words:4:pos":"particle","grammar:2092:ex4:words:5:zh":"(shows a state of possession)","grammar:2092:ex4:words:5:pos":"verb","grammar:2092:ex4:words:6:zh":"(polite tone)","grammar:2092:ex4:words:6:pos":"auxiliary verb","grammar:2092:ex4:points:0":"「太い」 directly modifies a noun and usually describes how thick a long, thin object is.","grammar:2092:ex4:points:1":"Depending on the situation, 「持っています」 can mean owning something or currently holding something.","grammar:2092:ex5:trans":"That fish has a thick body.","grammar:2092:ex5:structure":"〜は＋body partが＋i-adjectiveです","grammar:2092:ex5:explain":"「あの魚は」 first points out the fish being described, and 「体が太いです」 then states a feature of its body. This pattern of the whole with 「は」 plus a part with 「が」 plus an adjective also appears in 「象は鼻が長いです」. 「太い」 is about thickness and is not the same as 「重い」 or 「太っている」.","grammar:2092:ex5:words:0:zh":"that","grammar:2092:ex5:words:0:pos":"pre-noun adjectival","grammar:2092:ex5:words:1:zh":"fish","grammar:2092:ex5:words:1:note":"さかな","grammar:2092:ex5:words:1:pos":"noun","grammar:2092:ex5:words:2:zh":"(topic)","grammar:2092:ex5:words:2:pos":"particle","grammar:2092:ex5:words:3:zh":"body","grammar:2092:ex5:words:3:note":"からだ","grammar:2092:ex5:words:3:pos":"noun","grammar:2092:ex5:words:4:zh":"(nominative)","grammar:2092:ex5:words:4:pos":"particle","grammar:2092:ex5:words:5:zh":"thick","grammar:2092:ex5:words:5:note":"ふとい","grammar:2092:ex5:words:5:pos":"i-adjective","grammar:2092:ex5:words:6:zh":"(polite tone)","grammar:2092:ex5:words:6:pos":"auxiliary verb","grammar:2092:ex5:points:0":"In 「魚は体が太い」, 「は」 brings up the whole, and 「が」 then describes one of its parts.","grammar:2092:ex5:points:1":"「あの」 modifies a noun and usually refers to something far from both the speaker and the listener.","grammar:2092:ex5:points:2":"「太い」 describes a thick shape; it does not directly mean being heavy."},"2093":{"example:2093:exzh":"I lost my key.","example:2093:exzh2":"Please lock the door.","example:2093:exzh3":"This key is for the drawer.","example:2093:exzh4":"I forgot the house key.","example:2093:exzh5":"The key broke, so I replaced it.","grammar:2093:ex:trans":"I've gone and lost the key.","grammar:2093:ex:structure":"have gone and lost the key","grammar:2093:ex:explain":"The core of this sentence is 「〜てしまう」, which expresses regret over something that cannot be undone. 「なくしてしまいました」 is the te-form of the transitive verb 「なくす」 (to lose) plus 「しまいました」; here 「〜てしまう」 means doing something carelessly or unfortunately and carries a tone of regret, which fits the frustration of losing a key perfectly. The 「を」 in 「鍵を」 marks the object. In the sentence, 「〜てしまう」 is the key to that chagrined tone; without it, all that is left is a neutral statement of fact.","grammar:2093:ex:words:0:zh":"key","grammar:2093:ex:words:0:note":"かぎ","grammar:2093:ex:words:0:pos":"noun","grammar:2093:ex:words:1:zh":"(object marker)","grammar:2093:ex:words:1:pos":"particle","grammar:2093:ex:words:2:zh":"to lose (something)","grammar:2093:ex:words:2:note":"なくして","grammar:2093:ex:words:2:pos":"verb","grammar:2093:ex:words:3:zh":"(carelessly) did","grammar:2093:ex:words:3:pos":"auxiliary verb","grammar:2093:ex:points:0":"❗カギ (鍵): key, lock, the key to something (kanji 「鍵」); 〜てしまう = to do … carelessly / unfortunately.","grammar:2093:ex:points:1":"カギ: key.","grammar:2093:ex2:trans":"Please lock the door.","grammar:2093:ex2:structure":"カギをかけてください","grammar:2093:ex2:words:0:zh":"lock","grammar:2093:ex2:words:0:note":"かぎ","grammar:2093:ex2:words:0:pos":"noun","grammar:2093:ex2:words:1:zh":"(object marker)","grammar:2093:ex2:words:1:pos":"particle","grammar:2093:ex2:words:2:zh":"to lock up","grammar:2093:ex2:words:2:note":"かけて","grammar:2093:ex2:words:2:pos":"verb","grammar:2093:ex2:words:3:zh":"please","grammar:2093:ex2:words:3:pos":"auxiliary verb","grammar:2093:ex2:points:0":"❗カギをかける: to lock up, to lock the door (set phrase; かける = to apply).","grammar:2093:ex2:points:1":"カギをかける: to lock up.","grammar:2093:ex3:trans":"This key is used for the desk drawer.","grammar:2093:ex3:structure":"このカギは〜引き出しに使います","grammar:2093:ex3:words:0:zh":"this","grammar:2093:ex3:words:0:pos":"pre-noun adjectival","grammar:2093:ex3:words:1:zh":"key","grammar:2093:ex3:words:1:note":"かぎ","grammar:2093:ex3:words:1:pos":"noun","grammar:2093:ex3:words:2:zh":"(topic)","grammar:2093:ex3:words:2:pos":"particle","grammar:2093:ex3:words:3:zh":"desk","grammar:2093:ex3:words:3:note":"つくえ","grammar:2093:ex3:words:3:pos":"noun","grammar:2093:ex3:words:4:zh":"'s","grammar:2093:ex3:words:4:pos":"particle","grammar:2093:ex3:words:5:zh":"drawer","grammar:2093:ex3:words:5:note":"ひきだし","grammar:2093:ex3:words:5:pos":"noun","grammar:2093:ex3:words:6:zh":"(object)","grammar:2093:ex3:words:6:pos":"particle","grammar:2093:ex3:words:7:zh":"use","grammar:2093:ex3:words:7:note":"つかいます","grammar:2093:ex3:words:7:pos":"verb","grammar:2093:ex3:points:0":"❗引き出し: drawer; カギを使う = to use a key.","grammar:2093:ex3:points:1":"引き出し: drawer.","grammar:2093:ex4:trans":"I forgot the house key.","grammar:2093:ex4:structure":"forgot the house key","grammar:2093:ex4:words:0:zh":"house","grammar:2093:ex4:words:0:note":"いえ","grammar:2093:ex4:words:0:pos":"noun","grammar:2093:ex4:words:1:zh":"'s","grammar:2093:ex4:words:1:pos":"particle","grammar:2093:ex4:words:2:zh":"key","grammar:2093:ex4:words:2:note":"かぎ","grammar:2093:ex4:words:2:pos":"noun","grammar:2093:ex4:words:3:zh":"(object marker)","grammar:2093:ex4:words:3:pos":"particle","grammar:2093:ex4:words:4:zh":"Forgot","grammar:2093:ex4:words:4:note":"わすれました","grammar:2093:ex4:words:4:pos":"verb","grammar:2093:ex4:points:0":"❗家のカギ: the house key; カギを忘れる = to forget the key.","grammar:2093:ex4:points:1":"家のカギ: the house key.","grammar:2093:ex5:trans":"The key broke, so I replaced it.","grammar:2093:ex5:structure":"the key broke, so I replaced it","grammar:2093:ex5:words:0:zh":"key","grammar:2093:ex5:words:0:note":"かぎ","grammar:2093:ex5:words:0:pos":"noun","grammar:2093:ex5:words:1:zh":"(nominative)","grammar:2093:ex5:words:1:pos":"particle","grammar:2093:ex5:words:2:zh":"broke","grammar:2093:ex5:words:2:note":"こわれた","grammar:2093:ex5:words:2:pos":"verb","grammar:2093:ex5:words:3:zh":"because","grammar:2093:ex5:words:3:pos":"particle","grammar:2093:ex5:words:4:zh":"replaced","grammar:2093:ex5:words:4:note":"こうかんしました","grammar:2093:ex5:words:4:pos":"verb","grammar:2093:ex5:points:0":"❗壊れる: to break (intransitive verb); 交換する = to replace.","grammar:2093:ex5:points:1":"壊れる: to break."},"2094":{"example:2094:exzh":"I show him respect.","example:2094:exzh2":"Please treat others with respect.","example:2094:exzh3":"I must show her respect.","example:2094:exzh4":"I pay respect to his achievements.","example:2094:exzh5":"Respect is important."},"2095":{"example:2095:exzh":"He's a decent person.","example:2095:exzh2":"I can't find a decent job.","example:2095:exzh3":"I want to talk about something serious.","example:2095:exzh4":"Her opinion is reasonable.","example:2095:exzh5":"Please give it some serious thought."},"2096":{"example:2096:exzh":"Using drugs requires caution.","example:2096:exzh2":"Over-the-counter drugs sometimes work right away.","example:2096:exzh3":"The problem of drug dependence is serious.","example:2096:exzh4":"He is receiving treatment for drug use.","example:2096:exzh5":"I want to deepen my understanding of drugs."},"2097":{"example:2097:exzh":"I've already gone beyond my limits.","example:2097:exzh2":"Do you ever feel you've reached your limit?","example:2097:exzh3":"It's important to know your own limits.","example:2097:exzh4":"I like the challenge of going beyond limits.","example:2097:exzh5":"He wants to test his limits."},"2098":{"example:2098:exzh":"I had a fight with a friend.","example:2098:exzh2":"Fighting isn't good.","example:2098:exzh3":"They fought over something small.","example:2098:exzh4":"Making up after a fight is important.","example:2098:exzh5":"He wants to avoid fighting.","grammar:2098:ex:trans":"I got into a fight with a friend.","grammar:2098:ex:structure":"I got into a fight with a friend","grammar:2098:ex:explain":"The core of this sentence is 「〜とケンカする」 with 「〜てしまう」. 「ケンカする」 is a する verb meaning to quarrel or fight, and the person you fight with, 「友達」, is marked with 「と」, because a quarrel is a mutual action that the other person takes part in — such reciprocal actions customarily take 「と」. 「してしまった」 is the te-form of 「する」 plus 「しまった」, and 「〜てしまう」 adds a tone of regret: I went and had a fight. The whole sentence, I got into a fight with a friend, uses 「と」 for the other party and 「〜てしまう」 for the regret, so the emotion comes through fully.","grammar:2098:ex:words:0:zh":"friend","grammar:2098:ex:words:0:note":"ともだち","grammar:2098:ex:words:0:pos":"noun","grammar:2098:ex:words:1:zh":"(object)","grammar:2098:ex:words:1:pos":"particle","grammar:2098:ex:words:2:zh":"to quarrel","grammar:2098:ex:words:2:note":"ケンカして","grammar:2098:ex:words:2:pos":"verb","grammar:2098:ex:words:3:zh":"(regrettably) did","grammar:2098:ex:words:3:pos":"auxiliary verb","grammar:2098:ex:points:1":"ケンカ: a quarrel.","grammar:2098:ex2:trans":"Fighting is not good.","grammar:2098:ex2:structure":"ケンカはよくないです","grammar:2098:ex2:words:0:zh":"fighting","grammar:2098:ex2:words:0:note":"ケンカ","grammar:2098:ex2:words:0:pos":"noun","grammar:2098:ex2:words:1:zh":"(topic)","grammar:2098:ex2:words:1:pos":"particle","grammar:2098:ex2:words:2:zh":"bad / not good","grammar:2098:ex2:words:2:pos":"adjective","grammar:2098:ex2:words:3:zh":"(polite form)","grammar:2098:ex2:words:3:pos":"copula","grammar:2098:ex2:points:0":"❗ケンカ = quarreling, fighting; よくない = not good.","grammar:2098:ex2:points:1":"ケンカはよくない: fighting is not good.","grammar:2098:ex3:trans":"They fought over something trivial.","grammar:2098:ex3:structure":"fought over something trivial","grammar:2098:ex3:words:0:zh":"they","grammar:2098:ex3:words:0:note":"かれら","grammar:2098:ex3:words:0:pos":"pronoun","grammar:2098:ex3:words:1:zh":"(topic)","grammar:2098:ex3:words:1:pos":"particle","grammar:2098:ex3:words:2:zh":"small","grammar:2098:ex3:words:2:note":"ちいさい","grammar:2098:ex3:words:2:pos":"adjective","grammar:2098:ex3:words:3:zh":"thing / matter","grammar:2098:ex3:words:3:pos":"noun","grammar:2098:ex3:words:4:zh":"(cause)","grammar:2098:ex3:words:4:pos":"particle","grammar:2098:ex3:words:5:zh":"quarreled","grammar:2098:ex3:words:5:note":"ケンカした","grammar:2098:ex3:words:5:pos":"verb","grammar:2098:ex3:points:0":"❗❓小さいことで = over something trivial (で = cause); ケンカする = to quarrel.","grammar:2098:ex3:points:1":"小さいことでケンカ: fighting over something trivial.","grammar:2098:ex4:trans":"Making up after a fight is important.","grammar:2098:ex4:structure":"Making up after a fight is important","grammar:2098:ex4:words:0:zh":"to quarrel","grammar:2098:ex4:words:0:note":"ケンカ","grammar:2098:ex4:words:0:pos":"noun","grammar:2098:ex4:words:1:zh":"(object marker)","grammar:2098:ex4:words:1:pos":"particle","grammar:2098:ex4:words:2:zh":"did","grammar:2098:ex4:words:2:pos":"verb","grammar:2098:ex4:words:3:zh":"later, afterwards","grammar:2098:ex4:words:3:note":"あと","grammar:2098:ex4:words:3:pos":"noun","grammar:2098:ex4:words:4:zh":"(point in time)","grammar:2098:ex4:words:4:pos":"particle","grammar:2098:ex4:words:5:zh":"(contrast)","grammar:2098:ex4:words:5:pos":"particle","grammar:2098:ex4:words:6:zh":"make up","grammar:2098:ex4:words:6:note":"なかなおり","grammar:2098:ex4:words:6:pos":"noun","grammar:2098:ex4:words:7:zh":"(nominative)","grammar:2098:ex4:words:7:pos":"particle","grammar:2098:ex4:words:8:zh":"important","grammar:2098:ex4:words:8:note":"たいせつ","grammar:2098:ex4:words:8:pos":"na-adjective","grammar:2098:ex4:words:9:zh":"(polite form)","grammar:2098:ex4:words:9:pos":"copula","grammar:2098:ex4:points:0":"❗仲直り: making up, reconciliation (仲 + 直り); ケンカをする = to quarrel.","grammar:2098:ex4:points:1":"仲直り: making up.","grammar:2098:ex5:trans":"He wants to avoid a fight.","grammar:2098:ex5:structure":"he wants to avoid a fight","grammar:2098:ex5:words:0:zh":"he","grammar:2098:ex5:words:0:note":"かれ","grammar:2098:ex5:words:0:pos":"pronoun","grammar:2098:ex5:words:1:zh":"(topic)","grammar:2098:ex5:words:1:pos":"particle","grammar:2098:ex5:words:2:zh":"quarrel","grammar:2098:ex5:words:2:note":"ケンカ","grammar:2098:ex5:words:2:pos":"noun","grammar:2098:ex5:words:3:zh":"(object marker)","grammar:2098:ex5:words:3:pos":"particle","grammar:2098:ex5:words:4:zh":"wants to avoid","grammar:2098:ex5:words:4:note":"さけたがっています","grammar:2098:ex5:words:4:pos":"verb","grammar:2098:ex5:points:0":"❗〜たがる: (for a third person) to want to …; ケンカを避ける = to avoid a conflict.","grammar:2098:ex5:points:1":"避けたがる: to want to avoid."},"2099":{"example:2099:exzh":"Putting together a summary of this information is hard work.","example:2099:exzh2":"I'll write the report summary this weekend.","example:2099:exzh3":"Once you've written the summary, please submit it.","example:2099:exzh4":"I'll explain after putting together the summary of the materials.","example:2099:exzh5":"The summary is finished."}};